window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch04"]={"id":"ch04","title":"第三章(二) 蛋白质运输","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"COP/网格蛋白小泡 · Rab · SNARE","modules":[{"i":0,"name":"模块一：运输途径与网格蛋白小泡","slides":[{"i":0,"sec":"第一节 概述","title":"蛋白质输入细胞器的3种途径 (p1)","notes":"蛋白质通过3种途径输入细胞器内：①囊泡运输(膜泡运输)——内膜系统中细胞器内部相互交流及与细胞外部联系主要靠小泡运输完成；②跨膜运输——线粒体、叶绿体、过氧化物酶体；③核孔运输——转运入细胞核。","page":1,"level":"掌握","img":"assets/img/ch04/p001.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"蛋白质输入细胞器有哪3种途径？","back":"囊泡运输（膜泡运输）；跨膜运输；核孔运输","mnemonic":"泡、跨、孔——三路进器","type":"流程","useImg":false,"blank":"囊泡运输","blank2":"跨膜运输"}]},{"i":1,"sec":"第一节 概述","title":"三种运输途径对应 (p2)","notes":"核孔运输→细胞核；跨膜运输→线粒体、叶绿体、信号肽引导新生肽链入ER；膜泡运输→内膜系统。Part II 蛋白质分选及运输。","page":2,"level":"掌握","img":"assets/img/ch04/p002.jpg","anim":"protein_input_pathways","fig":"蛋白质输入细胞器有三条途径：①核孔运输——大分子经核孔复合体进出细胞核；②跨膜运输——线粒体、叶绿体、过氧化物酶体的蛋白由导肽/转运肽引导跨膜进入，信号肽则引导新生肽链入 ER；③膜泡运输——内膜系统各细胞器之间及与质膜之间靠运输小泡。图左侧画出蛋白在胞质合成后分别去核、去线粒体等、去 ER。","points":null,"check":{"q":"根据三种运输途径的对应关系，跨膜运输主要将蛋白质运送到下列哪一组目的地？","o":["A. 细胞核","B. 线粒体、叶绿体以及由信号肽引导新生肽链进入内质网","C. 高尔基体、溶酶体、胞内体","D. 质膜和细胞外"],"a":"B","e":"跨膜运输对应线粒体、叶绿体及信号肽引导新生肽链入ER；核孔运输对应细胞核，膜泡运输对应内膜系统。","oe":["运往细胞核的是核孔运输，不是跨膜运输。","跨膜运输将蛋白运往线粒体、叶绿体及经信号肽进入ER。","高尔基体、溶酶体、胞内体由膜泡运输运送。","质膜和细胞外由膜泡运输即分泌途径完成。"]},"cards":[{"front":"核孔运输、跨膜运输、膜泡运输分别对应哪些目的地？","back":"核孔运输→细胞核；跨膜运输→线粒体、叶绿体、过氧化物酶体（及信号肽引导入ER）；膜泡运输→内膜系统","mnemonic":"核走孔，线叶过走跨，内膜走泡","type":"对比","useImg":false,"blank":"核孔运输","blank2":"膜泡运输"}]},{"i":2,"sec":"第一节 概述","title":"共翻译转移 (p3)","notes":"1 共翻译转移：蛋白质起始合成后共转移至粗面内质网，蛋白通过不同类型的转运小泡从rER→Golgi→胞内体、溶酶体、液泡、质膜、分泌到胞外。","page":3,"level":"掌握","img":"assets/img/ch04/p003.jpg","anim":null,"fig":null,"points":["共翻译转运：蛋白边翻译边进入 ER(信号肽)。","翻译后转运：蛋白在胞质合成完成后，再转运到线粒体/叶绿体/过氧化物酶体。","核孔运输：经核孔复合体的选择性、主动运输。"],"check":{"q":"关于共翻译转移，下列叙述正确的是？","o":["A. 蛋白质在游离核糖体中完全合成后再转运到内质网","B. 蛋白质起始合成后即共转移至粗面内质网，再经转运小泡从rER→Golgi→胞内体、溶酶体、液泡、质膜或分泌到胞外","C. 共翻译转移只发生在细胞核内","D. 共翻译转移的蛋白质最终只进入线粒体"],"a":"B","e":"共翻译转移指蛋白质起始合成后共转移至粗面内质网，随后通过不同类型转运小泡从rER经Golgi运往胞内体、溶酶体、液泡、质膜或分泌到胞外。","oe":["蛋白质是边合成边转移，而非完全合成后再转运到内质网。","蛋白质起始合成后即共转移至rER，再经小泡运往各目的地。","共翻译转移发生在粗面内质网，不在细胞核内。","共翻译转移的蛋白目的地多样，不只进入线粒体。"]},"cards":[{"front":"什么是共翻译转移？","back":"蛋白质起始合成后即共转移至粗面内质网；再经转运小泡从rER→Golgi→胞内体、溶酶体、液泡、质膜或分泌到胞外","mnemonic":"边合成边进ER，一路泡到膜外","type":"定义","useImg":false,"blank":"共转移","blank2":"粗面内质网"}]},{"i":3,"sec":"第一节 概述","title":"翻译后转移 (p4)","notes":"2 翻译后转移：合成的蛋白质在细胞质基质游离核糖体中完成，然后转运至特定部位。跨膜转运蛋白质由胞质溶胶→线粒体、叶绿体、过氧化物酶体等细胞器。","page":4,"level":"掌握","img":"assets/img/ch04/p004.jpg","anim":null,"fig":"翻译后转移：蛋白质在细胞质基质游离核糖体上合成完毕后，再转运到特定部位。图中列出两种翻译后转运方式：②跨膜转运——蛋白以解析叠形式、借助分子伴侣进入线粒体、叶绿体、过氧化物酶体等；③核孔运输——蛋白以折叠组装形式、携带 NLS 经核孔复合体进出细胞核。","points":null,"check":{"q":"翻译后转移的特点是？","o":["A. 蛋白质在粗面内质网附着核糖体上合成并同时转运","B. 蛋白质在细胞质基质游离核糖体中完成合成后，再转运至线粒体、叶绿体、过氧化物酶体等特定部位","C. 蛋白质合成后只能留在细胞质基质中","D. 蛋白质通过核孔进入细胞核后再转运到线粒体"],"a":"B","e":"翻译后转移指蛋白质在细胞质基质游离核糖体中完成合成后，再跨膜转运至线粒体、叶绿体、过氧化物酶体等细胞器。","oe":["在rER附着核糖体上边合成边转运属于共翻译转移。","翻译后转移指在游离核糖体完成合成后再转运至线粒体等部位。","翻译后转移的蛋白可运往多种细胞器，并非只留在胞质。","经核孔入核属于核孔运输，不是翻译后转移途径。"]},"cards":[{"front":"什么是翻译后转移？","back":"蛋白质在细胞质基质游离核糖体中合成完成后，再转运至特定部位；如由胞质溶胶→线粒体、叶绿体、过氧化物酶体等","mnemonic":"先译完，再搬家","type":"定义","useImg":false,"blank":"游离核糖体","blank2":"细胞质基质"}]},{"i":4,"sec":"第一节 概述","title":"2013年诺贝尔生理学或医学奖 (p5)","notes":"2013年诺贝尔生理学或医学奖授予发现细胞囊泡运输调节机制(膜泡运输的分子原理)——James Rothman、Randy Schekman、Thomas Südhof。\n\n【本页英文讲解】\n本页为2013年诺贝尔生理学或医学奖，表彰发现细胞囊泡运输（vesicular transport）的调节机制。获奖者为James Rothman、Randy Schekman与Thomas Südhof，他们揭示了货物蛋白如何被准确分选、运送与释放的规则。此为翟中和《细胞生物学》第4版第八章蛋白质分选与膜泡运输的经典导入，常考诺奖得主与贡献的对应。","page":5,"level":"掌握","img":"assets/img/ch04/p005.jpg","anim":null,"fig":null,"points":["2013 年诺贝尔生理学或医学奖授予 Rothman、Schekman、Südhof。","表彰他们发现细胞囊泡运输的调节机制。","囊泡运输是蛋白质定向输送的核心机制。"],"check":null,"cards":[{"front":"2013年诺贝尔生理学或医学奖授予了谁？因何贡献？","back":"James Rothman、Randy Schekman、Thomas Südhof；发现细胞囊泡运输的调节机制（膜泡运输的分子原理）","mnemonic":"三巨头：R-S-S，囊泡运输","type":"例证","useImg":false,"blank":"囊泡运输","blank2":"调节机制"}]},{"i":5,"sec":"第一节 概述","title":"囊泡运输的分子原理 (p6)","notes":"the molecular principles that govern how this cargo is delivered to the correct location——阐明货物如何被运送到正确位置的分子原理，是囊泡运输的核心问题。\n\n【本页英文讲解】\n本页聚焦囊泡运输的核心问题：阐明货物（cargo）如何被运送到正确位置的分子原理（molecular principles）。细胞内有多种膜性区室，新合成的蛋白质必须被精确分选并定向投递，才能各就各位。该原理涉及包被组装、货物的选择性装载、小泡的定向运输与靶膜识别融合等环节，是第八章的主线，也是理解COPII、Rab、SNARE等机制的基础。","page":6,"level":"掌握","img":"assets/img/ch04/p006.jpg","anim":null,"fig":null,"points":["囊泡运输要解决三个问题：货物选择性装载、定向运输到正确靶膜、与靶膜融合。","对应三类分子：包被蛋白(选择货物)、Rab(控制停靠)、SNARE(介导融合)。"],"check":{"q":"囊泡运输的核心分子原理主要阐明的是？","o":["A. 货物如何被运送到正确位置的分子机制","B. 蛋白质如何在内质网中折叠","C. 核糖体如何组装","D. DNA如何复制"],"a":"A","e":"囊泡运输的分子原理旨在阐明货物如何被运送到正确位置，这是囊泡运输的核心问题。","oe":["囊泡运输的核心原理阐明货物如何被运送到正确位置。","蛋白质在ER中折叠属于ER功能，不是囊泡运输核心问题。","核糖体组装属于核仁功能，与囊泡运输无关。","DNA复制发生在细胞核内，与囊泡运输无关。"]},"cards":[{"front":"囊泡运输的核心科学问题是什么？","back":"阐明货物如何被运送到正确位置的分子原理（the molecular principles that govern how this cargo is delivered to the correct location）","back2":"","mnemonic":"货要对门——分子原理","type":"功能","useImg":false,"blank":"分子原理","blank2":"货物"}]},{"i":6,"sec":"第二节 小泡类型","title":"小泡运输的3种小泡类型 (p7)","notes":"Types of Vesicle Transport：①转运小泡(COPII，ER→Golgi)；②COPI小泡(Golgi→ER，回收)；③网格蛋白有被小泡(Golgi→质膜/溶酶体、受体介导的胞吞)。\n\n【本页英文讲解】\n本页概述囊泡运输的三种小泡类型：（1）转运小泡，即COPII有被小泡，介导内质网（ER）到高尔基体的运输；（2）COPI小泡，介导高尔基体到内质网的逆向回收；（3）网格蛋白有被小泡（clathrin-coated vesicle），介导高尔基体TGN到质膜、溶酶体以及受体介导的胞吞。考点：分清各小泡的方向与包被蛋白，这是判断运输路径的关键。","page":7,"level":"掌握","img":"assets/img/ch04/p007.jpg","anim":null,"fig":null,"points":["运输小泡由供体区室出芽形成，可运送可溶性蛋白和膜蛋白。","三种主要包被小泡：网格蛋白小泡、COPII、COPI。","小泡的外被蛋白与靶膜相互作用决定运输方向。"],"check":null,"cards":[{"front":"小泡运输的3种小泡类型及其主要运输方向？","back":"①转运小泡COPII：ER→Golgi；②COPI小泡：Golgi→ER（回收）；③网格蛋白有被小泡：Golgi→质膜/溶酶体、受体介导的胞吞","mnemonic":"II出ER，I回ER，网格去膜/溶酶","type":"组成数字","useImg":true,"blank":"转运小泡COPII","blank2":"COPI小泡"}]},{"i":7,"sec":"第二节 小泡类型","title":"内膜系统的有组织运输 (p8)","notes":"在内膜系统中膜被区室间的小泡转运是高度有组织的：①向外分泌途径——从ER蛋白质生物合成开始，通过Golgi到细胞表面或溶酶体；②向内的胞吞途径。","page":8,"level":"掌握","img":"assets/img/ch04/p008.jpg","anim":null,"fig":"囊泡运输总览：供体区室出芽 → 运输小泡 → 与靶膜停靠并融合 → 释放货物。图中不同颜色小泡代表不同包被(网格/COPII/COPI)，分别负责不同方向的运输。记住“出芽—运输—停靠—融合—卸载”五步。","points":null,"check":{"q":"关于内膜系统中膜被区室间的小泡转运，下列描述正确的是？","o":["A. 小泡转运是随机无序的","B. 小泡转运高度有组织，包括从ER开始经Golgi到细胞表面或溶酶体的向外分泌途径，以及向内的胞吞途径","C. 只有向内的胞吞途径，没有向外分泌途径","D. 小泡转运只发生在细胞核与细胞质之间"],"a":"B","e":"内膜系统中膜被区室间的小泡转运高度有组织，包括向外分泌途径（ER→Golgi→细胞表面或溶酶体）和向内的胞吞途径。","oe":["小泡转运高度有序，不是随机无序的。","小泡转运高度有组织，包括向外分泌途径和向内胞吞途径。","小泡转运既有胞吞途径，也有向外分泌途径。","小泡转运发生在内膜系统区室间，不限于核质之间。"]},"cards":[{"front":"内膜系统小泡转运的两条有组织途径是什么？","back":"①向外分泌途径：从ER蛋白质生物合成开始，经Golgi到细胞表面或溶酶体；②向内的胞吞途径","mnemonic":"一出（分泌）一进（胞吞）","type":"流程","useImg":true,"blank":"向外分泌途径","blank2":"胞吞途径"}]},{"i":8,"sec":"第二节 小泡类型","title":"三种包被蛋白小泡电镜图 (p9)","notes":"三种不同包被蛋白包裹小泡的电镜照片：COPII、COPI、网格蛋白小泡形态各异，包被蛋白决定小泡的运输方向。","page":9,"level":"理解","img":"assets/img/ch04/p009.jpg","anim":"coated_vesicles","fig":"三种包被小泡的形态与组成：①网格蛋白(clathrin)三脚复合体组成蜂巢状包被，负责质膜↔内体/溶酶体、TGN 出发的运输；②COPII 由 Sec23/24 与 Sec13/31 组成，负责 ER→Golgi 顺行；③COPI 由 β′/α 等组成，负责 Golgi→ER 逆行。下方是三种小泡的电镜照片。","points":null,"check":null,"cards":null},{"i":9,"sec":"第三节 网格蛋白","title":"网格蛋白有被小泡 (p10)","notes":"膜泡运输1：网格蛋白有被小泡(Clathrin-coated vesicle)，负责蛋白从Golgi TGN→质膜、溶酶体，以及受体介导的胞吞作用。\n\n【本页英文讲解】\n本页介绍网格蛋白有被小泡（clathrin-coated vesicle）。它由网格蛋白（clathrin）在膜外侧组装成笼状包被，负责把蛋白质从高尔基体反面网络（TGN）运往质膜和溶酶体，也参与受体介导的胞吞作用（receptor-mediated endocytosis）。考点：网格蛋白有被小泡的来源区室与去向，以及它在受体介导内吞中的角色。","page":10,"level":"掌握","img":"assets/img/ch04/p010.jpg","anim":"clathrin_endocytosis","fig":"网格蛋白有被小泡(clathrin-coated vesicle)：网格蛋白在膜外侧形成支架，衔接蛋白(adaptor)在内侧连接货物受体。TGN 是网格蛋白小泡的主要来源之一，货物去溶酶体/质膜。小 G 蛋白参与调控。","points":null,"check":null,"cards":[{"front":"网格蛋白有被小泡负责哪些运输途径？","back":"Golgi TGN→质膜、溶酶体；受体介导的胞吞","mnemonic":"TGN出货，两头到：膜与溶酶体","type":"功能","useImg":false,"blank":"受体介导的胞吞","blank2":"质膜"}]},{"i":10,"sec":"第三节 网格蛋白","title":"网格蛋白结构 (p11)","notes":"网格蛋白由3条重链(heavy chain)和3条轻链(light chain)组成，形成三脚蛋白复合体(triskelion)，组装成多边形网格包被小泡。","page":11,"level":"掌握","img":"assets/img/ch04/p011.jpg","anim":"clathrin_triskelion","fig":"网格蛋白由 3 条重链和 3 条轻链组成三脚复合体(triskelion)。三条臂能相互连接，组装成五边形/六边形网格，把膜拉成有被小泡。图展示了重链、轻链和“组装”的连接方式。","points":null,"check":null,"cards":[{"front":"网格蛋白由哪些链组成？形成什么复合体？","back":"3条重链+3条轻链；组成三脚蛋白复合体(triskelion)","mnemonic":"三足鼎立，三三成对","type":"组成数字","useImg":true,"blank":"三脚蛋白复合体"}]},{"i":11,"sec":"第三节 网格蛋白","title":"网格蛋白小泡结构 (p12)","notes":"网格蛋白小泡结构：网格蛋白外壳+衔接蛋白AP(adaptor protein)+货物受体。衔接蛋白在网格蛋白与货物受体间起中介接头作用。扫描电镜显示小泡的形成。","page":12,"level":"掌握","img":"assets/img/ch04/p012.jpg","anim":null,"fig":"网格蛋白小泡的结构：外层是网格蛋白网格，内层是衔接蛋白(AP)，最内是货物受体。网格蛋白本身不选择货物，选择货物的是衔接蛋白。图强调“包被蛋白—衔接蛋白—货物受体”三层结构。","points":null,"check":{"q":"网格蛋白小泡结构中，衔接蛋白AP的主要作用是？","o":["A. 直接水解ATP提供能量","B. 在网格蛋白与货物受体之间起中介接头作用","C. 构成小泡的脂双层","D. 负责小泡与靶膜的融合"],"a":"B","e":"网格蛋白小泡由网格蛋白外壳、衔接蛋白AP和货物受体组成，其中衔接蛋白在网格蛋白与货物受体间起中介接头作用。","oe":["AP无ATP酶活性，不能直接水解ATP为包被组装供能。","AP一端结合网格蛋白、一端结合货物受体，在两者间起中介接头作用。","小泡脂双层来自供体膜，AP是衔接蛋白，并不构成脂双层。","小泡与靶膜融合由SNARE介导，AP不负责膜融合。"]},"cards":[{"front":"网格蛋白小泡由哪三层结构组成？","back":"网格蛋白外壳；衔接蛋白AP；货物受体","mnemonic":"壳—接—货，三层包","type":"组成数字","useImg":true,"blank":"网格蛋白外壳","blank2":"衔接蛋白AP"},{"front":"衔接蛋白(AP)在包被小泡中的作用是什么？","back":"中介接头作用；连接网格蛋白与货物受体","mnemonic":"AP当红娘，牵壳与受体","type":"功能","useImg":true,"blank":"中介接头作用","blank2":"货物受体"}]},{"i":12,"sec":"第三节 网格蛋白","title":"包被小泡的组成 (p13)","notes":"①网格蛋白clathrin——外壳；②衔接蛋白(adaptor protein, AP)——中介接头作用，连接网格蛋白与货物受体；③发动蛋白Dynamin——小G蛋白，负责小泡从膜上掐断。","page":13,"level":"掌握","img":"assets/img/ch04/p013.jpg","anim":null,"fig":"网格蛋白参与的内吞：①网格蛋白在膜内侧组装成有被小窝；②衔接蛋白 AP 连接货物受体；③发动蛋白(dynamin)在颈部形成环并收缩，把有被小泡从膜上掐断。关键分子是 clathrin、adaptor、dynamin。","points":null,"check":{"q":"在包被小泡的组成中，负责将小泡从膜上掐断的是？","o":["A. 网格蛋白clathrin","B. 衔接蛋白AP","C. 发动蛋白Dynamin","D. 货物受体"],"a":"C","e":"发动蛋白Dynamin是一种小G蛋白，负责小泡从膜上掐断；网格蛋白构成外壳，衔接蛋白起中介接头作用。","oe":["网格蛋白构成小泡外壳，起包被作用，不负责将小泡掐断。","衔接蛋白AP在网格蛋白与货物受体间起接头作用，不负责掐断。","发动蛋白Dynamin是小G蛋白，在囊泡颈部成环并收缩使小泡断离。","货物受体负责识别并募集货物，不参与小泡从膜上掐断。"]},"cards":[{"front":"包被小泡的三大组成及各自功能？","back":"网格蛋白—外壳；衔接蛋白AP—接头；发动蛋白Dynamin—掐断","mnemonic":"壳、接、断，三件套","type":"组成数字","useImg":false,"blank":"发动蛋白Dynamin","blank2":"网格蛋白—外壳"}]},{"i":13,"sec":"第三节 网格蛋白","title":"网格蛋白小泡功能(i) (p14)","notes":"网格蛋白有被小泡：(i) Golgi TGN腔内的蛋白分子被浓缩入小泡内向外运输→质膜、溶酶体。","page":14,"level":"掌握","img":"assets/img/ch04/p014.jpg","anim":null,"fig":"网格蛋白有被小泡的形成：TGN 膜上的货物受体结合信号 → 衔接蛋白连接 → 网格蛋白组装成包被 → 出芽。图说明“包被决定方向，货物信号决定内容”。","points":null,"check":{"q":"关于网格蛋白有被小泡的功能(i)，下列叙述正确的是？","o":["A. Golgi TGN腔内的蛋白分子被浓缩入小泡内，向外运输至质膜、溶酶体","B. 网格蛋白有被小泡只负责从质膜向内运输","C. 网格蛋白有被小泡只运输脂类","D. 网格蛋白有被小泡将蛋白质运入细胞核"],"a":"A","e":"网格蛋白有被小泡功能(i)表现为Golgi TGN腔内的蛋白分子被浓缩入小泡内，向外运输至质膜、溶酶体。","oe":["网格蛋白小泡可将TGN腔内浓缩的蛋白向外运至质膜、溶酶体。","网格蛋白小泡既参与胞吞内运，也参与TGN向外运输，并非只向内。","网格蛋白小泡主要运输蛋白质等，并非只运输脂类物质。","蛋白质入核经核孔复合体，网格蛋白小泡不进入细胞核。"]},"cards":[{"front":"网格蛋白有被小泡从TGN出芽运输什么？","back":"TGN腔内浓缩的蛋白分子；运向质膜、溶酶体","mnemonic":"TGN浓缩打包，外送膜与溶酶体","type":"功能","useImg":false,"blank":"蛋白分子","blank2":"TGN腔内浓缩的蛋白分子"}]},{"i":14,"sec":"第三节 网格蛋白","title":"受体介导的内吞(ii) (p15)","notes":"(ii) 网格蛋白参与受体介导的内吞作用(receptor-mediated endocytosis)：细胞外特殊的生物大分子(如LDL)与质膜受体结合→网格蛋白小泡形成→内吞。","page":15,"level":"掌握","img":"assets/img/ch04/p015.jpg","anim":null,"fig":"受体介导的胞吞作用：细胞外的配体(如 LDL、转铁蛋白)先与质膜上的受体结合，再经网格蛋白有被小窝内吞。图显示受体-配体复合物被包进小泡，是“选择性摄取”的机制。","points":null,"check":null,"cards":[{"front":"受体介导的内吞作用中网格蛋白扮演什么角色？","back":"细胞外大分子(如LDL)与质膜受体结合后；网格蛋白参与小泡形成并内吞","mnemonic":"配体敲门，网格蛋白包走","type":"例证","useImg":false,"blank":"网格蛋白","blank2":"质膜受体"}]},{"i":15,"sec":"第三节 网格蛋白","title":"受体介导内吞步骤 (p16)","notes":"Receptor-mediated endocytosis：卵黄脂蛋白等配体与受体结合→膜凹陷→网格蛋白包被→形成小泡→内吞入胞。\n\n【本页英文讲解】\n本页介绍受体介导内吞（receptor-mediated endocytosis）的步骤：以卵黄脂蛋白等配体（ligand）与细胞膜上的受体（receptor）特异性结合为起始，随后膜局部凹陷，网格蛋白（clathrin）在胞质侧包被，形成有被小泡，最终内吞入胞。考点：配体与受体结合、膜凹陷、网格蛋白包被、小泡形成这一顺序，以及有被小泡脱包被后与内体融合。","page":16,"level":"掌握","img":"assets/img/ch04/p016.jpg","anim":null,"fig":"鸡卵母细胞摄取卵黄脂蛋白的步骤：配体与受体结合 → 网格蛋白有被小窝 → 有被小泡 → 脱包被 → 与内体融合。电镜图显示卵黄脂蛋白颗粒在胞质中被摄取。这是受体介导胞吞的经典实例。","points":null,"check":{"q":"受体介导内吞过程中，配体与受体结合后，膜凹陷处形成的包被主要含有哪种蛋白？","o":["A. 网格蛋白","B. 肌动蛋白","C. 角蛋白","D. 胶原蛋白"],"a":"A","e":"受体介导内吞时，膜凹陷处由网格蛋白组装形成包被，进而形成小泡。","oe":["受体介导内吞时质膜凹陷处由网格蛋白组装成有被小窝。","肌动蛋白属细胞骨架成分，参与运动，不是内吞包被主要蛋白。","角蛋白是细胞中间纤维成分，不参与构成内吞包被。","胶原蛋白是细胞外基质蛋白，与内吞包被无关。"]},"cards":[{"front":"受体介导内吞的基本步骤？","back":"配体与受体结合；膜凹陷；网格蛋白包被；形成小泡内吞入胞","mnemonic":"结合—凹陷—包被—入胞","type":"流程","useImg":true,"blank":"网格蛋白","blank2":"膜凹陷"}]},{"i":16,"sec":"第三节 网格蛋白","title":"发动蛋白dynamin作用 (p17)","notes":"胞吞作用中，小GTP蛋白dynamin与网格蛋白介导的膜泡运输：dynamin提供能量、引起环收缩，从而将小泡从膜上掐下来。","page":17,"level":"掌握","img":"assets/img/ch04/p017.jpg","anim":"dynamin_scission","fig":"发动蛋白(dynamin)在胞吞小泡颈部组装成螺旋环，水解 GTP 使环收缩，把有被小泡从质膜上“掐断”。抗 dynamin 抗体实验说明：即使出芽，若 dynamin 不工作，小泡也无法脱落。","points":null,"check":null,"cards":[{"front":"发动蛋白(dynamin)在胞吞中的作用？","back":"小GTP蛋白；提供能量、引起环收缩；将小泡从膜上掐断","mnemonic":"dynamin收绳，一掐了之","type":"功能","useImg":true,"blank":"小GTP蛋白","blank2":"环收缩"}]},{"i":17,"sec":"第三节 网格蛋白","title":"网格蛋白胞吞作用 (p18)","notes":"网格蛋白参与的受体介导的胞吞作用示意图：展示配体-受体结合、网格蛋白组装、dynamin收缩、小泡释放的完整过程。","page":18,"level":"理解","img":"assets/img/ch04/p018.jpg","anim":null,"fig":"胆固醇的运输（本页为文字要点，无示意图）：细胞经网格蛋白参与的受体介导胞吞作用，从细胞外液摄取胆固醇、维生素 B₁₂、铁等特定大分子。下方列举实例：动物细胞摄取胆固醇、鸟类卵细胞摄取卵黄蛋白、肝细胞摄入转铁蛋白。","points":null,"check":{"q":"在网格蛋白介导的胞吞作用中，负责收缩并促使小泡从质膜上断离的蛋白是？","o":["A. Sar蛋白","B. dynamin","C. COPI","D. 载脂蛋白B"],"a":"B","e":"dynamin在网格蛋白包被小泡颈部收缩，使小泡从质膜释放。","oe":["Sar是COPII组装相关小G蛋白，位于内质网出芽处，与胞吞掐断无关。","dynamin在网格蛋白小泡颈部收缩，水解GTP使小泡从质膜断离。","COPI参与高尔基体的逆向运输，不负责胞吞小泡断离。","载脂蛋白B是LDL外壳蛋白，不参与小泡从膜上掐断。"]},"cards":null},{"i":18,"sec":"第三节 网格蛋白","title":"LDL与胆固醇代谢 (p19)","notes":"LDL和胆固醇代谢：动物细胞中胆固醇是质膜重要组成成分，并作为类固醇激素的前体分子。胆固醇极难溶解，主要以LDL(低密度脂蛋白)形式在血液中运输。","page":19,"level":"掌握","img":"assets/img/ch04/p019.jpg","anim":null,"fig":"LDL 和胆固醇代谢：肝脏合成胆固醇和 LDL → 血液运输 → 组织细胞表面 LDL 受体结合 → 内吞 → 溶酶体降解释放游离胆固醇。图强调受体介导摄取是调节血胆固醇的关键。","points":null,"check":null,"cards":[{"front":"动物细胞中胆固醇的两大作用是什么？","back":"质膜重要组成成分；类固醇激素前体分子","mnemonic":"膜上站岗，激素原料","type":"功能","useImg":false,"blank":"类固醇激素前体分子","blank2":"质膜重要组成成分"},{"front":"胆固醇在血液中主要以什么形式运输？为什么？","back":"LDL（低密度脂蛋白）；胆固醇极难溶解，需脂蛋白载体","mnemonic":"难溶靠LDL摆渡","type":"定义","useImg":false,"blank":"LDL","blank2":"低密度脂蛋白"}]},{"i":19,"sec":"第三节 网格蛋白","title":"LDL结构 (p20)","notes":"LDL结构：核心为胆固醇酯(约1500分子)，外壳为磷脂、胆固醇、载脂蛋白B。LDL通过受体介导的胞吞进入细胞。","page":20,"level":"掌握","img":"assets/img/ch04/p020.jpg","anim":null,"fig":"LDL 颗粒结构：核心是约 1500 个胆固醇酯(疏水)，外被单层磷脂、游离胆固醇和载脂蛋白 apoB-100。apoB-100 是 LDL 受体的配体。图说明“核心疏水、外壳亲水、apoB-100 识别受体”。","points":null,"check":{"q":"关于LDL结构的描述，下列哪项正确？","o":["A. 核心为磷脂，外壳为胆固醇酯","B. 核心为胆固醇酯，外壳含磷脂、胆固醇和载脂蛋白B","C. 核心为载脂蛋白B，外壳为胆固醇酯","D. 仅由胆固醇酯和载脂蛋白B组成，不含磷脂"],"a":"B","e":"LDL核心为约1500分子胆固醇酯，外壳由磷脂、胆固醇和载脂蛋白B构成。","oe":["LDL核心是胆固醇酯而非磷脂，外壳才含磷脂，该描述颠倒。","LDL核心约1500分子胆固醇酯，外壳含磷脂、胆固醇和载脂蛋白B。","载脂蛋白B位于LDL外壳，核心为胆固醇酯，此项描述颠倒。","LDL外壳含磷脂，并非仅由胆固醇酯和载脂蛋白B组成。"]},"cards":[{"front":"LDL颗粒的核心和外壳各由什么组成？","back":"核心：胆固醇酯（约1500分子）；外壳：磷脂、胆固醇、载脂蛋白B","mnemonic":"核酯壳脂，B蛋白把门","type":"组成数字","useImg":true,"blank":"载脂蛋白B","blank2":"胆固醇酯"},{"front":"LDL通过什么方式进入细胞？","back":"受体介导的胞吞","mnemonic":"受体点名，胞吞进门","type":"流程","useImg":true,"blank":"受体介导的胞吞"}]},{"i":20,"sec":"第三节 网格蛋白","title":"LDL受体途径 (p21)","notes":"基本过程：①细胞需要胆固醇时合成LDL跨膜受体蛋白并插入质膜；②受体与LDL颗粒结合后形成网格蛋白包被小泡；③小泡脱包被与溶酶体融合；④胆固醇释放利用。","page":21,"level":"掌握","img":"assets/img/ch04/p021.jpg","anim":"ldl_pathway","fig":null,"points":null,"check":{"q":"LDL受体途径中，LDL与受体结合后形成的小泡接下来会经历什么过程？","o":["A. 直接与高尔基体融合","B. 脱包被后与溶酶体融合","C. 直接与内质网融合","D. 直接与细胞核融合"],"a":"B","e":"LDL受体途径中，网格蛋白包被小泡脱包被后与溶酶体融合，释放胆固醇供细胞利用。","oe":["LDL内吞形成的包被小泡不与高尔基体直接融合。","包被小泡脱包被后与溶酶体融合，胆固醇酯水解释放胆固醇供利用。","LDL小泡不直接与内质网融合，需经胞内体与溶酶体途径。","LDL小泡不进入细胞核，核与LDL受体途径无关。"]},"cards":[{"front":"LDL受体途径的四个基本步骤是什么？","back":"①需胆固醇时合成LDL受体插入质膜；②受体结合LDL形成网格蛋白包被小泡；③脱包被后与溶酶体融合；④胆固醇释放利用","mnemonic":"合成—结合—融合—释放","type":"流程","useImg":true,"blank":"溶酶体","blank2":"网格蛋白包被小泡"}]},{"i":21,"sec":"第三节 网格蛋白","title":"LDL受体胞吞途径 (p22)","notes":"Endocytic pathway for LDL receptor：LDL受体介导的胞吞途径，展示LDL结合、内吞、溶酶体降解、受体回收的循环。\n\n【本页英文讲解】\n本页展示低密度脂蛋白（LDL）受体介导的胞吞途径（endocytic pathway for LDL receptor）。LDL与细胞膜上LDL受体结合后，膜凹陷并经网格蛋白包被形成小泡进入细胞；随后在溶酶体中被降解，释放胆固醇供细胞利用，而受体则可回收再循环到质膜。考点：LDL受体缺陷可致家族性高胆固醇血症，是经典例证。","page":22,"level":"理解","img":"assets/img/ch04/p022.jpg","anim":null,"fig":"LDL 内吞途径：LDL 与质膜 LDL 受体结合 → 网格蛋白有被小泡 → 脱包被、与内体融合 → 内体酸性 pH 使受体与 LDL 分离 → 受体回收、LDL 送溶酶体降解 → 释放游离胆固醇。图的关键是“受体循环使用”。","points":null,"check":null,"cards":null},{"i":22,"sec":"第三节 网格蛋白","title":"家族性高胆固醇血症 (p23)","notes":"编码LDL受体蛋白的基因缺失、或受体存在但无功能→胆固醇摄入通路阻断→细胞不能摄取胆固醇→血液胆固醇升高→家族性高胆固醇血症。","page":23,"level":"掌握","img":"assets/img/ch04/p023.jpg","anim":null,"fig":"编码 LDL 受体的基因缺失或受体无功能 → 细胞不能摄取 LDL → 血胆固醇升高 → 胆固醇沉积在动脉壁 → 动脉粥样硬化。图显示正常与缺陷的对比，是“受体介导胞吞”的经典疾病模型。","points":null,"check":null,"cards":[{"front":"家族性高胆固醇血症的病因是什么？","back":"LDL受体基因缺失或受体无功能；胆固醇摄入通路阻断，血胆固醇升高","mnemonic":"受体失灵，血脂飙升","type":"例证","useImg":false,"blank":"LDL受体基因缺失","blank2":"胆固醇摄入通路阻断"}]},{"i":23,"sec":"第三节 网格蛋白","title":"转铁蛋白循环 (p24)","notes":"The transferrin cycle：在所有生长的哺乳动物细胞中运转——转铁蛋白结合铁，经受体介导胞吞进入细胞释放铁，受体和转铁蛋白回收循环。","page":24,"level":"理解","img":"assets/img/ch04/p024.jpg","anim":"transferrin_cycle","fig":"转铁蛋白(transferrin)循环：转铁蛋白结合 Fe³⁺ → 与质膜转铁蛋白受体结合 → 内吞 → 内体酸性环境释放铁 → 转铁蛋白-受体返回质膜循环使用。图强调受体和载体都可反复利用。","points":null,"check":null,"cards":null}],"mcq":[{"id":"ch04_mcq_1","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"蛋白质输入细胞器不包括下列哪种途径？","o":["A. 囊泡运输","B. 跨膜运输","C. 核孔运输","D. 简单扩散"],"a":"D","e":"蛋白质输入细胞器3途径：囊泡运输(内膜系统)、跨膜运输(线粒体/叶绿体/过氧化物酶体)、核孔运输(细胞核)。蛋白质是大分子，不能简单扩散。","kp":"ch04_s0_0"},{"id":"ch04_mcq_2","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"2013年诺贝尔生理学或医学奖授予？","o":["A. 囊泡运输调节机制","B. 水通道","C. RNAi","D. 泛素降解"],"a":"A","e":"2013年诺贝尔奖授予Rothman、Schekman、Südhof，发现细胞囊泡运输的调节机制。","kp":"ch04_s0_4"},{"id":"ch04_mcq_3","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"负责ER→高尔基体顺行运输的小泡是？","o":["A. COPII","B. COPI","C. 网格蛋白小泡","D. 溶酶体"],"a":"A","e":"COPII小泡负责ER→Golgi顺行运输；COPI小泡负责Golgi→ER逆向回收；网格蛋白小泡负责TGN→质膜/溶酶体及胞吞。","kp":"ch04_s0_6"},{"id":"ch04_mcq_4","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"负责回收逃逸蛋白返回ER的小泡是？","o":["A. COPII","B. COPI","C. 网格蛋白","D. 核孔"],"a":"B","e":"COPI小泡负责回收、转运ER逃逸蛋白返回ER，含7个亚基和ARF(GTP结合蛋白)。","kp":"ch04_s0_9"},{"id":"ch04_mcq_5","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"网格蛋白有被小泡的组成不包括？","o":["A. 网格蛋白","B. 衔接蛋白AP","C. 发动蛋白Dynamin","D. Sar蛋白"],"a":"D","e":"Sar蛋白参与COPII组装；网格蛋白小泡由网格蛋白+衔接蛋白AP+发动蛋白dynamin组成。","kp":"ch04_s0_9"},{"id":"ch04_mcq_6","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"发动蛋白(dynamin)的功能是？","o":["A. 组装网格蛋白","B. 提供能量、引起环收缩,将小泡从膜上掐下来","C. 识别货物","D. 催化融合"],"a":"B","e":"dynamin是小GTP蛋白，在胞吞中提供能量、引起环收缩，将小泡从膜上掐断。","kp":"ch04_s0_16"},{"id":"ch04_mcq_7","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"家族性高胆固醇血症的分子基础是？","o":["A. LDL受体基因缺失或无功能","B. 胆固醇过多","C. 网格蛋白过多","D. SRP缺陷"],"a":"A","e":"LDL受体基因缺失或受体无功能→胆固醇摄入通路阻断→细胞不能摄取胆固醇→血胆固醇升高。","kp":"ch04_s0_22"},{"id":"ch04_mcq_8","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"ER驻留蛋白逃逸后如何被回收？","o":["A. 经KDEL信号被受体识别,由COPI小泡回收","B. 直接降解","C. 分泌到胞外","D. 变成膜蛋白"],"a":"A","e":"ER驻留蛋白C端含KDEL回收信号，逃逸到高尔基体后被KDEL受体识别，经COPI小泡回收回ER。","kp":"ch04_s0_23"},{"id":"ch04_mcq_9","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"Rab蛋白属于？","o":["A. GTP酶超家族的开关蛋白","B. 网格蛋白","C. 衔接蛋白","D. 蛋白酶"],"a":"A","e":"Rab属于GTP酶超家族的开关蛋白，有60多种，高度选择性地分布在不同膜上，控制小泡停靠。","kp":"ch04_s0_0"},{"id":"ch04_mcq_10","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"v-SNARE与t-SNARE的关系是？","o":["A. 都位于同一膜","B. v-SNARE在小泡、t-SNARE在靶膜,互补配对介导融合","C. 都是网格蛋白","D. 都是Rab"],"a":"B","e":"v-SNARE在小泡表面、t-SNARE在靶膜上，两者互补配对形成反式SNARE复合物，介导膜融合。","kp":null},{"id":"ch04_mcq_11","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"COPII小泡组装依赖的GTP结合蛋白是？","o":["A. Sar","B. ARF","C. Rab","D. Dynamin"],"a":"A","e":"Sar-GTP结合ER膜，诱导COPII蛋白亚单位组装。COPI依赖ARF，网格蛋白胞吞依赖dynamin。","kp":"ch04_s0_8"},{"id":"ch04_mcq_12","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"受体介导的胞吞作用中,负责将小泡从膜上掐断的是？","o":["A. 网格蛋白","B. 发动蛋白dynamin","C. 衔接蛋白","D. SNARE"],"a":"B","e":"dynamin在小泡颈部形成环并收缩，消耗GTP将小泡从质膜上掐断。","kp":"ch04_s0_14"}],"judge":[{"id":"ch04_judge_1","modI":0,"q":"蛋白质输入细胞器有囊泡运输、跨膜运输和核孔运输三种途径。","a":"对","e":"三种途径：囊泡运输(内膜系统)、跨膜运输(线粒体/叶绿体/过氧化物酶体)、核孔运输(细胞核)。","kp":"ch04_s0_0"},{"id":"ch04_judge_3","modI":0,"q":"网格蛋白由3条重链和3条轻链组成三脚复合体。","a":"对","e":"网格蛋白由3条重链和3条轻链组成三脚复合体(triskelion)，组装成网格包被。","kp":"ch04_s0_10"},{"id":"ch04_judge_4","modI":0,"q":"发动蛋白(dynamin)是一种小GTP蛋白，能将小泡从膜上掐断。","a":"对","e":"dynamin在胞吞小泡颈部形成环并收缩，消耗GTP将小泡从膜上掐断。","kp":"ch04_s0_16"},{"id":"ch04_judge_8","modI":0,"q":"家族性高胆固醇血症的分子基础是LDL受体基因缺失或受体无功能。","a":"对","e":"LDL受体缺陷→胆固醇摄入通路阻断→血胆固醇升高。","kp":"ch04_s0_22"},{"id":"ch04_judge_9","modI":0,"q":"受体介导的胞吞作用中，LDL被降解而受体也随之被降解，不能回收。","a":"错","e":"LDL在溶酶体被降解，而受体可回收并循环利用。","kp":"ch04_s0_21"},{"id":"ch04_judge_10","modI":0,"q":"2013年诺贝尔生理学或医学奖授予发现细胞囊泡运输调节机制的科学家。","a":"对","e":"2013年授予Rothman、Schekman、Südhof，发现细胞囊泡运输的调节机制。","kp":"ch04_s0_4"}],"fill":[{"id":"ch04_fill_1","modI":0,"q":"蛋白质输入细胞器的3种途径是________、________和________。","a":"囊泡运输(膜泡运输),跨膜运输,核孔运输","kp":"ch04_s0_0"},{"id":"ch04_fill_3","modI":0,"q":"网格蛋白由3条________和3条________组成三脚复合体；衔接蛋白AP起________作用。","a":"重链,轻链,中介接头","kp":"ch04_s0_10"},{"id":"ch04_fill_4","modI":0,"q":"发动蛋白dynamin是________蛋白,提供能量并引起环收缩,将小泡从膜上________。","a":"小G(GTP),掐断","kp":"ch04_s0_16"},{"id":"ch04_fill_8","modI":0,"q":"家族性高胆固醇血症的分子基础是________受体基因缺失或受体无功能。","a":"LDL","kp":"ch04_s0_22"},{"id":"ch04_fill_9","modI":0,"q":"2013年诺贝尔生理学或医学奖授予发现________调节机制的三位科学家。","a":"细胞囊泡运输","kp":"ch04_s0_4"},{"id":"ch04_fill_11","modI":0,"q":"LDL颗粒的核心是________,外壳含磷脂、胆固醇和________。","a":"胆固醇酯,载脂蛋白B","kp":"ch04_s0_18"}],"short":[{"id":"ch04_short_1","modI":0,"q":"简述膜泡运输的三种类型及其功能。","a":"膜泡运输的三种小泡类型：\n\n①COPII有被小泡(ER→Golgi)：负责从内质网到高尔基体的顺行运输。组装依赖GTP结合蛋白Sar。\n\n②COPI有被小泡(Golgi→ER)：负责回收、转运ER的逃逸蛋白返回ER，也参与高尔基体内部逆向运输。有7个蛋白亚基，依赖ARF。\n\n③网格蛋白有被小泡(Clathrin-coated vesicle)：负责从Golgi TGN→质膜、溶酶体的运输，以及受体介导的胞吞作用。由网格蛋白(triskelion)+衔接蛋白AP+发动蛋白dynamin组成。\n\n【共同点】\n①都由包被蛋白在膜上组装形成；\n②包被蛋白决定运输方向和货物选择；\n③小泡形成后脱去包被，经Rab/SNARE与靶膜识别并融合。\n\n【意义】\n实现内膜系统区室间及细胞与外界之间的物质运输。","kp":"ch04_s0_5"},{"id":"ch04_short_2","modI":0,"q":"简述受体介导的胞吞作用(以LDL为例)。","a":"受体介导的胞吞作用(receptor-mediated endocytosis)：\n\n【以LDL(低密度脂蛋白)为例】\n①LDL结构：核心为约1500分子胆固醇酯，外壳为磷脂、胆固醇和载脂蛋白B。\n②当细胞需要胆固醇时，合成LDL跨膜受体蛋白并插入质膜。\n③质膜上的LDL受体与LDL颗粒结合。\n④膜凹陷，网格蛋白组装，形成网格蛋白包被小泡。\n⑤发动蛋白dynamin在颈部形成环并收缩(GTP供能)，将小泡从膜上掐断。\n⑥小泡脱包被，与溶酶体融合，LDL被降解，胆固醇释放利用，受体回收。\n\n【病理】\n编码LDL受体基因缺失或受体无功能→胆固醇摄入通路阻断→家族性高胆固醇血症。\n\n【意义】\n高效、特异摄取胞外大分子，是细胞摄取胆固醇、铁(转铁蛋白)等的重要方式。","kp":"ch04_s0_14"},{"id":"ch04_short_4","modI":0,"q":"比较COPII、COPI和网格蛋白小泡。","a":"三种包被小泡的比较：\n\n| 类型 | 方向 | 包被蛋白 | GTP酶 | 功能 |\n|---|---|---|---|---|\n| COPII | ER→Golgi | COPII(Sec23/24等) | Sar | 顺行运输 |\n| COPI | Golgi→ER | COPI(7亚基) | ARF | 回收逃逸蛋白 |\n| 网格蛋白 | TGN→质膜/溶酶体；胞吞 | 网格蛋白+AP | dynamin/ARF | 分泌、受体介导胞吞 |\n\n【共同点】\n①都在膜上组装包被；②都依赖小GTP酶调控装配；③都脱包被后经Rab/SNARE融合。\n\n【意义】\n不同包被蛋白决定小泡的运输方向与货物选择性。","kp":"ch04_s0_11"},{"id":"ch04_short_6","modI":0,"q":"为什么说囊泡运输研究重要？简述其发现史。","a":"囊泡运输的重要性与发现史：\n\n【重要性】\n①囊泡运输是真核细胞内膜系统区室间物质交流的主要方式；\n②完成分泌蛋白的运输、胞吞、溶酶体酶分选等基本生命活动；\n③缺陷与多种疾病相关(如家族性高胆固醇血症、神经退行性疾病)；\n④是细胞极性和组织功能的基础。\n\n【发现史】\n①1974年Palade等用放射自显影追踪分泌蛋白路径；\n②1990年代Schekman用酵母遗传学筛选到sec突变体，发现COPII等；\n③Rothman发现SNARE蛋白介导膜融合；\n④Südhof发现神经递质释放的钙感受器；\n⑤2013年Rothman、Schekman、Südhof获诺贝尔生理学或医学奖。\n\n【核心分子】\n包被蛋白(COPII/COPI/网格蛋白)、小G蛋白(Sar/ARF/Rab/dynamin)、SNARE。","kp":"ch04_s0_5"}],"calc":[{"id":"ch04_calc_1","modI":0,"q":"论述膜泡运输的分子机制(从出芽到融合)。","a":"膜泡运输经历出芽、运输、停靠、融合四个阶段,由多组分子协同完成","steps":"【1. 出芽(budding)】\n①包被蛋白在供体膜上组装：COPII(Sar)、COPI(ARF)、网格蛋白(AP)；\n②货物蛋白经信号序列与受体结合，被浓缩入小泡；\n③网格蛋白/COPII形成弯曲的膜，dynamin(GTP)收缩掐断小泡。\n\n【2. 运输(transport)】\n①短距离靠扩散；\n②长距离靠细胞骨架(微管/马达蛋白)运输。\n\n【3. 停靠(docking)】\n①小泡脱去包被；\n②Rab-GTP与靶膜Rab effector结合→识别、锚定、停靠。\n\n【4. 融合(fusion)】\n①v-SNARE(小泡)与t-SNARE(靶膜)互补配对形成反式SNARE复合物；\n②SNARE缠绕拉近两膜；\n③NSF/SNAP等胞质蛋白参与，驱动膜融合；\n④货物释放。\n\n【调控】\n各步骤由小GTP酶(Sar/ARF/Rab/dynamin)精确调控。\n\n【意义】\n保证货物精准投递；2013年诺贝尔奖。","kp":"ch04_s0_5"},{"id":"ch04_calc_3","modI":0,"q":"论述受体介导的胞吞作用及其在医学上的意义。","a":"受体介导的胞吞是细胞特异、高效摄取胞外大分子的方式,其缺陷导致疾病","steps":"【机制(以LDL为例)】\n①配体(LDL)与质膜受体特异结合；\n②膜凹陷，网格蛋白组装成包被小泡；\n③dynamin收缩掐断小泡；\n④脱包被，与溶酶体融合，配体降解，受体回收循环。\n\n【特点】\n①高度特异(受体-配体)；\n②高效(浓缩富集)；\n③受体可循环利用。\n\n【其他例子】\n①转铁蛋白循环(摄铁)；\n②卵黄脂蛋白摄取；\n③病毒/毒素入侵途径。\n\n【医学意义】\n①家族性高胆固醇血症：LDL受体基因缺失/无功能→胆固醇摄入阻断→动脉粥样硬化；\n②药物靶向：利用受体介导胞吞递送药物；\n③病原体利用此途径感染(如病毒)；\n④为基因治疗、纳米药物设计提供思路。","kp":"ch04_s0_14"}],"term":[{"id":"ch04_term_1","modI":0,"term":"膜泡运输(Vesicular Transport)","def":"①通过膜性小泡在细胞器间运输物质的方式（定义）。②三种小泡：COPII(ER→Golgi)、COPI(Golgi→ER回收)、网格蛋白小泡(TGN→质膜/溶酶体、胞吞)（类型）。③过程：出芽→运输→停靠→融合（过程）。④意义：内膜系统区室间物质交流的主要方式（意义）。","kps":"踩分点:①定义(1分)②三种小泡(1分)③过程(1分)④意义(1分)","kp":"ch04_s0_6"},{"id":"ch04_term_4","modI":0,"term":"网格蛋白有被小泡(Clathrin-coated Vesicle)","def":"①由网格蛋白包被的小泡（定义）。②组成：网格蛋白(3重链+3轻链三脚复合体)+衔接蛋白AP+发动蛋白dynamin（组成）。③功能：Golgi TGN→质膜/溶酶体运输；受体介导的胞吞作用（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(2分)","kp":"ch04_s0_9"},{"id":"ch04_term_5","modI":0,"term":"发动蛋白(Dynamin)","def":"①参与胞吞的小GTP蛋白（定义）。②功能：提供能量、引起环收缩，将小泡从膜上掐断（功能）。③位置：网格蛋白小泡颈部（位置）。","kps":"踩分点:①定义(1分)②功能(2分)③位置(1分)","kp":"ch04_s0_16"},{"id":"ch04_term_6","modI":0,"term":"受体介导的胞吞作用","def":"①细胞通过质膜受体特异结合胞外大分子并内吞的过程（定义）。②过程：配体-受体结合→网格蛋白包被→dynamin掐断→脱包被→与溶酶体融合（过程）。③举例：LDL(胆固醇)、转铁蛋白(铁)（举例）。④病理：LDL受体缺陷→家族性高胆固醇血症（病理）。","kps":"踩分点:①定义(1分)②过程(1分)③举例(1分)④病理(1分)","kp":"ch04_s0_14"},{"id":"ch04_term_12","modI":0,"term":"家族性高胆固醇血症","def":"①由LDL受体基因缺陷导致的遗传病（定义）。②机制：LDL受体缺失或无功能→胆固醇摄入通路阻断→细胞不能摄取胆固醇→血液胆固醇升高→动脉粥样硬化（机制）。③意义：是受体介导胞吞重要性的经典例证（意义）。","kps":"踩分点:①定义(1分)②机制(2分)③意义(1分)","kp":"ch04_s0_22"},{"id":"ch04_term_13","modI":0,"term":"衔接蛋白(Adaptor Protein, AP)","def":"①网格蛋白小泡中连接网格蛋白与货物受体的蛋白（定义）。②功能：中介接头作用，选择货物并将其与网格蛋白连接（功能）。③意义：决定网格蛋白小泡的货物选择性（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch04_s0_11"}]},{"i":1,"name":"模块二：COP小泡与停靠融合","slides":[{"i":0,"sec":"第四节 COPII","title":"COPII有被小泡 (p25)","notes":"膜泡运输2：COPII有被小泡(ER→Golgi)——COPII-coated vesicles move materials from the ER。负责从ER到高尔基体的顺行运输。\n\n【本页英文讲解】\n本页介绍COPII有被小泡（COPII-coated vesicle）。COPII包被的小泡负责把内质网（ER）内合成的蛋白质运出，移向高尔基体，即从ER到高尔基体的顺行（anterograde）运输。COPII由Sar1、Sec23/Sec24、Sec13/Sec31等蛋白组成。考点：COPII的方向是ER→Golgi，与COPI的逆向回收方向相反。","page":25,"level":"掌握","img":"assets/img/ch04/p025.jpg","anim":"copii_budding","fig":"COPII 有被小泡负责 ER→Golgi 顺行运输。COPII 由 Sec23/24 复合体(内层，结合货物)和 Sec13/31 复合体(外层，形成支架)组成。图显示纯化的 COPII 蛋白在脂膜上聚合，形成高度弯曲的芽。","points":null,"check":null,"cards":[{"front":"COPII有被小泡负责什么方向的运输？","back":"从内质网（ER）到高尔基体的顺行运输","mnemonic":"COPII向前走：ER→Golgi","type":"定位","useImg":true,"blank":"顺行运输","blank2":"内质网"}]},{"i":1,"sec":"第四节 COPII","title":"Sar蛋白与COPII组装 (p26)","notes":"Sar-GTP binds to the ER；GTP激发Sar构型变化，诱导COPII蛋白亚单位(Sec23/Sec24、Sec13/Sec31等)组装到ER膜上，形成COPII包被。\n\n【本页英文讲解】\n本页讲解Sar蛋白与COPII包被的组装。Sar-GTP结合到内质网（ER）膜上；GTP的结合激发Sar的构型变化，进而诱导COPII蛋白亚单位（如Sec23/Sec24、Sec13/Sec31等）在ER膜上组装，形成COPII包被。该过程体现GTP酶的构象开关作用。考点：Sar1是COPII组装的关键，属GTP结合蛋白，其活化触发货物装载与膜出芽。","page":26,"level":"掌握","img":"assets/img/ch04/p026.jpg","anim":null,"fig":"COPII 装配由小 G 蛋白 Sar1 启动：Sar-GDP 被 GEF 活化 → Sar-GTP 插入 ER 膜 → 招募 Sec23/24 → 招募 Sec13/31 → 出芽。Sar1 水解 GTP 后脱落。图强调“Sar1 是 COPII 装配的开关”。","points":null,"check":null,"cards":[{"front":"Sar-GTP如何启动COPII包被组装？","back":"Sar-GTP结合ER膜；GTP激发Sar构型变化，诱导Sec23/Sec24、Sec13/Sec31等组装成COPII包被","mnemonic":"Sar变构，COPII集合","type":"流程","useImg":true,"blank":"Sar-GTP","blank2":"COPII包被"}]},{"i":2,"sec":"第四节 COPII","title":"Sar蛋白活化 (p27)","notes":"Sar-GDP→Sar-GTP：激活Sar蛋白，使Sar-GTP与ER膜结合，启动COPII小泡的组装。Sar是GTP结合蛋白。\n\n【本页英文讲解】\n本页说明Sar蛋白的活化：Sar-GDP转变为Sar-GTP，被激活后Sar-GTP与内质网（ER）膜结合，启动COPII小泡的组装。Sar是一种GTP结合蛋白（GTP-binding protein），其活性受鸟苷酸状态调控，类似开关。考点：Sar1的GTP与GDP循环决定COPII包被的组装与解聚，是膜泡出芽调控的核心；掌握GTP结合为活化态这一规律。","page":27,"level":"掌握","img":"assets/img/ch04/p027.jpg","anim":null,"fig":"COPII 有被小泡的装配：Sar1-GTP 结合 ER 膜 → Sec23/24 识别货物受体 → Sec13/31 形成外支架 → 膜弯曲出芽 → GTP 水解、包被脱落。图是 COPII 从装配到出芽的完整流程。","points":null,"check":{"q":"Sar蛋白活化启动COPII小泡组装时，其活性形式是？","o":["A. Sar-GDP","B. Sar-GTP","C. Sar-ATP","D. Sar-AMP"],"a":"B","e":"Sar-GDP转变为Sar-GTP后被激活，Sar-GTP与ER膜结合并启动COPII小泡组装。","oe":["Sar-GDP是无活性形式，需转变为GTP结合态才能被激活。","Sar-GDP转变为Sar-GTP后被激活，结合ER膜并启动COPII组装。","Sar是GTP结合蛋白，其活性形式结合GTP而非ATP。","Sar不结合AMP，不存在Sar-AMP这一活性形式。"]},"cards":[{"front":"Sar蛋白如何被激活？其本质是什么？","back":"Sar-GDP→Sar-GTP；Sar-GTP与ER膜结合，启动COPII小泡组装；Sar是GTP结合蛋白","mnemonic":"换GTP上岗，贴膜开工","type":"定义","useImg":false,"blank":"GTP结合蛋白","blank2":"COPII小泡组装"}]},{"i":3,"sec":"第五节 COPI","title":"COPI有被小泡 (p28)","notes":"膜泡运输3：COPI有被小泡(COPI-coated vesicle)——负责回收、转运ER的逃逸蛋白返回ER，也参与高尔基体内部的逆向运输。","page":28,"level":"掌握","img":"assets/img/ch04/p028.jpg","anim":"copi_retrieval","fig":"COPI 有被小泡负责 Golgi→ER 逆行运输，把逃逸的 ER 驻留蛋白回收回 ER。COPI 由 α、β、β′ 等亚基组成，装配依赖小 G 蛋白 ARF。图显示 COPI 小泡从高尔基体膜出芽。","points":null,"check":{"q":"COPI有被小泡的主要功能是？","o":["A. 将蛋白质从ER运往高尔基体","B. 回收逃逸蛋白返回ER并参与高尔基体内部逆向运输","C. 将蛋白质从高尔基体运往溶酶体","D. 介导LDL进入细胞"],"a":"B","e":"COPI有被小泡负责回收ER逃逸蛋白返回ER，也参与高尔基体内部的逆向运输。","oe":["ER→高尔基体的顺行运输由COPII小泡负责，不是COPI。","COPI回收逃逸蛋白返回ER，并参与高尔基体内部的逆向运输。","高尔基体→溶酶体运输主要经网格蛋白等小泡，非COPI。","LDL进入细胞经网格蛋白介导的胞吞，与COPI无关。"]},"cards":[{"front":"COPI有被小泡的两大功能是什么？","back":"回收、转运ER逃逸蛋白返回ER；参与高尔基体内部逆向运输","mnemonic":"COPI向后撤：回ER、退高尔基","type":"功能","useImg":true,"blank":"逆向运输","blank2":"ER逃逸蛋白"}]},{"i":4,"sec":"第五节 COPI","title":"驻留蛋白的保留机制 (p29)","notes":"如何确定一种蛋白是否被保留在ER或Golgi？两种机制：①转运小泡根据信号序列将应保留的驻留蛋白(resident protein)留下；②逃逸蛋白经回收信号被回收。","page":29,"level":"掌握","img":"assets/img/ch04/p029.jpg","anim":null,"fig":"如何确定蛋白被保留在 ER/Golgi？两种机制：①驻留(retention)——ER 驻留蛋白被排斥、不能进入出芽小泡；②回收(retrieval)——逃逸的驻留蛋白被受体捕获，经 COPI 小泡运回 ER。图强调“回收信号”是主要机制。","points":null,"check":{"q":"关于驻留蛋白保留机制，下列哪项描述正确？","o":["A. 驻留蛋白通过信号序列被转运小泡留下，逃逸蛋白经回收信号被回收","B. 驻留蛋白直接被降解，逃逸蛋白被运往细胞外","C. 驻留蛋白通过网格蛋白包被小泡运出ER","D. 驻留蛋白与LDL受体结合后被保留"],"a":"A","e":"驻留蛋白可依据信号序列被转运小泡留下，逃逸蛋白则通过回收信号被回收。","oe":["驻留蛋白凭信号序列被转运小泡留下，逃逸蛋白经回收信号被回收。","驻留蛋白并非直接被降解，逃逸蛋白也不会被运往细胞外。","驻留蛋白由COPI小泡回收，不经网格蛋白小泡运出ER。","驻留蛋白的保留与LDL受体无关，机制在ER和高尔基体。"]},"cards":[{"front":"驻留蛋白被保留在ER或Golgi的两种机制是什么？","back":"①转运小泡依信号序列将驻留蛋白留下；②逃逸蛋白经回收信号被回收","mnemonic":"留下+抓回，双保险","type":"流程","useImg":false,"blank":"回收信号","blank2":"驻留蛋白"}]},{"i":5,"sec":"第五节 COPI","title":"回收信号 (p30)","notes":"回收信号(retrieval signal)：ER的正常驻留蛋白，无论在ER腔或膜上，其C端均有一段回收信号序列(如KDEL)。如果ER驻留蛋白逃逸到高尔基体，会被KDEL受体识别并经COPI小泡回收回ER。","page":30,"level":"掌握","img":"assets/img/ch04/p030.jpg","anim":"kdel_retrieval","fig":"回收信号：ER 驻留蛋白(Bip、PDI 等)C 端都有回收信号 KDEL(Lys-Asp-Glu-Leu)。若逃逸到高尔基体 CGN，被 KDEL 受体识别，经 COPI 小泡运回 ER。图说明“ER is an open prison”——门虽开着，但有回收机制。","points":null,"check":null,"cards":[{"front":"ER驻留蛋白的回收信号是什么？位于何处？","back":"C端回收信号序列，如KDEL；ER腔或膜上的驻留蛋白均有","mnemonic":"KDEL——Keep in ER","type":"定义","useImg":false,"blank":"KDEL","blank2":"驻留蛋白"},{"front":"ER驻留蛋白逃逸到高尔基体后如何被回收？","back":"被KDEL受体识别，经COPI小泡回收回ER","mnemonic":"KDEL受体+COPI=遣返专车","type":"流程","useImg":false,"blank":"KDEL受体","blank2":"COPI小泡"}]},{"i":6,"sec":"第五节 COPI","title":"COPI组成 (p31)","notes":"COPI包被膜泡：有7个蛋白亚基，以及ARF(类似COPII的Sar蛋白)，是一种GTP结合蛋白。包被复合物的装配/去装配依赖于ARF。","page":31,"level":"掌握","img":"assets/img/ch04/p031.jpg","anim":null,"fig":"COPI 有被膜泡：由 7 个亚基组成，装配依赖 ARF 小 G 蛋白。ARF-GDP→ARF-GTP 后插入膜，招募 COPI。COPI 小泡的货物含 KDEL/KKXX 信号。图是 COPI 装配与出芽的过程。","points":null,"check":null,"cards":[{"front":"COPI包被膜泡由哪些成分组成？","back":"7个蛋白亚基；ARF（GTP结合蛋白，类似COPII的Sar）","mnemonic":"七亚基+ARF","type":"组成数字","useImg":false,"blank":"ARF","blank2":"GTP结合蛋白"},{"front":"COPI包被复合物的装配与去装配依赖什么？","back":"ARF（GTP结合蛋白）","mnemonic":"ARF开关，装拆自如","type":"功能","useImg":false,"blank":"ARF","blank2":"GTP结合蛋白"}]},{"i":7,"sec":"第六节 小结","title":"网格蛋白介导的运输 (p32)","notes":"网格蛋白介导由高尔基体TGN向质膜、胞内体或溶酶体的运输(顺行转运，小G蛋白ARF)，以及受体介导的胞吞作用(小G蛋白dynamin)。","page":32,"level":"掌握","img":"assets/img/ch04/p032.jpg","anim":"vesicle_compare","fig":"三种膜泡比较：①COPII——ER→Golgi 顺行，小 G 蛋白 SAR；②网格蛋白——TGN→质膜/内体/溶酶体顺行(ARF)，以及受体介导胞吞(dynamin)；③COPI——Golgi→ER 逆行，小 G 蛋白 ARF。图下方的膜流图给出顺行/逆行两条方向。","points":["COPII：ER→Golgi 顺行，SAR；COPI：Golgi→ER 逆行，ARF；网格蛋白：TGN→质膜/内体/溶酶体，ARF/dynamin。"],"check":null,"cards":[{"front":"网格蛋白介导的运输有哪两类方向？各由什么小G蛋白参与？","back":"①TGN→质膜/胞内体/溶酶体（顺行转运），ARF；②受体介导的胞吞，dynamin","mnemonic":"出站ARF，进站dynamin","type":"对比","useImg":false,"blank":"dynamin","blank2":"ARF"}]},{"i":8,"sec":"第七节 停靠融合","title":"小泡运输的停靠和融合 (p33)","notes":"二、小泡运输的停靠和融合机制：小泡出芽离开膜后必须找到正确目的地交货。①距离短(如ER→Golgi)靠扩散运动；②距离长需细胞骨架(马达蛋白)运输。","page":33,"level":"掌握","img":"assets/img/ch04/p033.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"小泡运输中，小泡如何到达正确目的地？","back":"①短距离靠扩散运动；②长距离需细胞骨架（马达蛋白）运输","mnemonic":"近走扩散，远搭骨架","type":"流程","useImg":false,"blank":"细胞骨架","blank2":"马达蛋白"}]},{"i":9,"sec":"第七节 停靠融合","title":"选择性融合 (p34)","notes":"运输小泡与靶膜的选择性融合——选择特异过程：如源于内质网的膜泡→高尔基体CGN区融合；源于中间膜囊的出芽膜泡→高尔基体特定区域融合。","page":34,"level":"掌握","img":"assets/img/ch04/p034.jpg","anim":null,"fig":"运输小泡与靶膜的选择性融合：Rab-SNARE 假说。①小泡出芽后必须找到正确的靶膜；②Rab GTPase 控制停靠；③v-/t-SNARE 互补配对介导融合。图强调全过程“严格专一”。","points":null,"check":{"q":"运输小泡与靶膜的选择性融合体现在？","o":["A. 所有小泡随机与任何膜融合","B. 源于内质网的膜泡与高尔基体CGN区融合，源于中间膜囊的出芽膜泡与高尔基体特定区域融合","C. 小泡只与溶酶体融合","D. 小泡只与细胞膜融合"],"a":"B","e":"运输小泡与靶膜的融合具有选择性，如ER来源膜泡与高尔基体CGN区融合，中间膜囊出芽膜泡与高尔基体特定区域融合。","oe":["小泡与靶膜融合具有高度选择性，并非随机与任何膜融合。","ER来源膜泡与高尔基体CGN融合，中间膜囊出芽膜泡与高尔基体特定区融合。","小泡并非只与溶酶体融合，靶膜具有多样性。","小泡并非只与细胞膜融合，还与前高尔基体等靶膜融合。"]},"cards":[{"front":"运输小泡与靶膜的选择性融合体现在哪里？","back":"ER来源膜泡→高尔基体CGN区融合；中间膜囊出芽膜泡→高尔基体特定区域融合","mnemonic":"各回各家，定点融合","type":"例证","useImg":false,"blank":"中间膜囊"}]},{"i":10,"sec":"第七节 停靠融合","title":"货物蛋白的靶向序列 (p35)","notes":"Targeting sequences(蛋白质信号序列) on cargo proteins make specific molecular interactions——货物蛋白上的信号序列与受体特异相互作用，保证正确定向。\n\n【本页英文讲解】\n本页讲货物蛋白的靶向序列（targeting sequences，即蛋白质信号序列）。货物蛋白（cargo protein）上带有特异的信号序列，可与相应受体发生特异的分子相互作用，从而保证被正确选择、定向装载进相应的小泡。这说明分选的特异性来自信号序列与受体间的分子识别。考点：信号序列是蛋白质分选的内在信息，与第八章蛋白质分选的总原则相呼应。","page":35,"level":"掌握","img":"assets/img/ch04/p035.jpg","anim":"rab_snare_hypothesis","fig":"Rab-SNARE 假说三要素：①货物蛋白的信号序列与包被蛋白特异结合(选择性装载)；②Rab GTPase 控制小泡在靶膜的停靠(docking)；③成对的 v-/t-SNARE 介导膜融合。图给出供体区室出芽到靶膜融合的全过程。","points":["货物信号序列—包被蛋白：选择装载；Rab GTPase：控制停靠；v-/t-SNARE 配对：介导融合。"],"check":null,"cards":[{"front":"货物蛋白如何保证被定向运输到正确部位？","back":"货物蛋白上的靶向信号序列与受体特异相互作用","mnemonic":"信号配受体，定向不迷路","type":"功能","useImg":false,"blank":"靶向信号序列","blank2":"受体"}]},{"i":11,"sec":"第七节 停靠融合","title":"Rab与SNARE (p36)","notes":"Rab(小G蛋白)控制转运小泡在靶膜的识别、锚定、停靠(docking)；v-SNARE/t-SNARE蛋白的配对结合介导运输小泡和靶膜的进一步融合。","page":36,"level":"掌握","img":"assets/img/ch04/p036.jpg","anim":"snare_fusion","fig":"Rab 与 SNARE（本页为文字说明）：①Rab 小 G 蛋白控制转运小泡在靶膜的识别、锚定与停靠(docking)；②v-SNARE 与 t-SNARE 配对结合，介导小泡与靶膜的进一步融合(fusion)。图中用红/蓝文字突出关键蛋白与步骤。","points":null,"check":null,"cards":[{"front":"Rab蛋白和SNARE蛋白在小泡运输中分别起什么作用？","back":"Rab（小G蛋白）控制小泡在靶膜的识别、锚定、停靠；v-SNARE/t-SNARE配对介导融合","mnemonic":"Rab找门，SNARE开门","type":"功能","useImg":false,"blank":"SNARE","blank2":"Rab"}]},{"i":12,"sec":"第七节 停靠融合","title":"Rab蛋白家族 (p37)","notes":"Rab proteins belong to the GTPase superfamily of switch proteins——Rab属于GTP酶超家族的开关蛋白，有60多种，每种定位到特定膜上。\n\n【本页英文讲解】\n本页介绍Rab蛋白家族。Rab蛋白属于GTP酶超家族中的开关蛋白（GTPase superfamily of switch proteins），在人类中有60多种，每种Rab定位于特定的膜或区室上，作为分子开关调控膜泡运输的不同步骤。其活性由GTP结合（活化）与GDP结合（失活）切换。考点：Rab种类繁多且定位特异，是膜泡运输调控的重要分子。","page":37,"level":"掌握","img":"assets/img/ch04/p037.jpg","anim":null,"fig":"Rab 蛋白属于 GTP 酶超家族：Rab-GDP 为非活化态，Rab-GTP 为活化态。不同膜上有不同的 Rab，每种细胞至少有几种 Rab。图说明 Rab 是“分子开关”，通过构象变化控制小泡运输。","points":null,"check":null,"cards":[{"front":"Rab蛋白属于哪个超家族？其数量与定位特点是什么？","back":"GTP酶超家族的开关蛋白；60多种；每种定位到特定膜上","mnemonic":"Rab是膜上的GPS开关","type":"定义","useImg":false,"blank":"GTP酶超家族","blank2":"开关蛋白"}]},{"i":13,"sec":"第七节 停靠融合","title":"Rab的定位 (p38)","notes":"Their highly selective distribution on these membrane systems makes Rab——Rab在膜系统上高度选择性的分布，使其成为膜身份的分子标志。\n\n【本页英文讲解】\n本页讲Rab的定位特征。Rab蛋白在各类膜系统上具有高度选择性的分布，每种Rab主要定位到特定膜或区室，因此其分布成为膜身份的分子标志（marker）。正因为这种特异性定位，Rab才能在不同运输步骤中精确地招募效应因子、指导小泡去向。考点：理解Rab通过选择性定位区分不同区室，是膜泡定向运输特异性的重要保障。","page":38,"level":"掌握","img":"assets/img/ch04/p038.jpg","anim":"rab_cycle","fig":"表格列出各 Rab 的亚细胞定位：Rab1(ER/高尔基体)、Rab2(顺面高尔基体)、Rab5(早期内体)、Rab7(晚期内体)等。Rab 的高度选择性分布使其成为识别膜系统的分子标志。记住几个代表性 Rab 即可。","points":null,"check":null,"cards":[{"front":"为什么说Rab是膜身份的分子标志？","back":"Rab在膜系统上高度选择性分布；不同膜有不同Rab","mnemonic":"一膜一Rab，如身份证","type":"功能","useImg":false,"blank":"Rab","blank2":"膜系统"}]},{"i":14,"sec":"第七节 停靠融合","title":"Rab与SNARE分工 (p39)","notes":"Rab proteins direct the vesicle to the correct target membrane, and SNARE proteins mediate fusion——Rab引导小泡到正确靶膜，SNARE介导融合。\n\n【本页英文讲解】\n本页阐明Rab与SNARE的分工：Rab蛋白负责引导小泡到达正确的靶膜（target membrane），而SNARE蛋白则介导小泡与靶膜的融合（fusion）。简言之，Rab管定向停靠，SNARE管膜融合，二者分工协作，共同保证运输的特异性与准确性。考点：这是膜泡运输定向与融合机制的核心结论，常以Rab与SNARE功能区别设题。","page":39,"level":"掌握","img":"assets/img/ch04/p039.jpg","anim":null,"fig":"Rab 蛋白引导小泡到达正确靶膜，SNARE 介导膜融合。三步：①tethering(系链，Rab 效应蛋白)——Rab-GTP 结合效应蛋白把两膜拉近；②docking(停靠)——v/t-SNARE 配对；③fusion(融合)——SNARE 复合体形成、膜融合。","points":null,"check":null,"cards":[{"front":"Rab与SNARE在膜泡运输中如何分工？","back":"Rab引导小泡到正确靶膜；SNARE介导膜融合","mnemonic":"Rab找路，SNARE开门","type":"对比","useImg":false,"blank":"SNARE","blank2":"Rab"}]},{"i":15,"sec":"第七节 停靠融合","title":"v-SNARE与t-SNARE (p40)","notes":"自膜芽生的小泡表面携带特定的v-SNARE(小泡SNARE)标志蛋白，能与靶膜上互补的t-SNARE(靶SNARE)结合。每一种小泡有其特异的v-SNARE。","page":40,"level":"掌握","img":"assets/img/ch04/p040.jpg","anim":null,"fig":"SNARE 蛋白：运输小泡上带 v-SNARE，靶膜上带 t-SNARE，二者互补配对。每种运输小泡和靶膜都有特异的 SNARE，保证小泡只与正确的膜融合。图对比 v-SNARE 与 t-SNARE 的配对。","points":null,"check":null,"cards":[{"front":"v-SNARE与t-SNARE分别位于哪里？","back":"v-SNARE在小泡表面；t-SNARE在靶膜上；二者互补结合","mnemonic":"v=vesicle，t=target","type":"定位","useImg":true,"blank":"t-SNARE","blank2":"v-SNARE"},{"front":"每种小泡的v-SNARE有何特点？","back":"每种小泡有其特异的v-SNARE","mnemonic":"专泡专SNARE","type":"定义","useImg":false,"blank":"v-SNARE","blank2":"小泡"}]},{"i":16,"sec":"第七节 停靠融合","title":"SNARE催化融合 (p41)","notes":"The SNARE proteins catalyze the membrane fusion reactions in vesicular transport——SNARE蛋白催化膜泡运输中的膜融合反应。v-SNARE与t-SNARE形成四螺旋束，拉近两膜。\n\n【本页英文讲解】\n本页介绍SNARE蛋白催化膜融合。SNARE（SNARE proteins）催化膜泡运输中的膜融合反应（membrane fusion）。位于小泡膜上的v-SNARE与靶膜上的t-SNARE相互识别，形成四螺旋束（four-helix bundle）拉近两膜。考点：SNARE是膜融合的核心机器，四螺旋束拉近两膜；注意v-SNARE与t-SNARE的来源区分。","page":41,"level":"掌握","img":"assets/img/ch04/p041.jpg","anim":null,"fig":"SNARE 蛋白催化囊泡运输中的膜融合，并提供“另一层特异性”——确保只有正确靶膜的小泡才融合。图说明 SNARE 是融合的“分子拉链”。","points":null,"check":{"q":"SNARE蛋白催化膜泡运输中膜融合反应的主要机制是？","o":["A. v-SNARE与t-SNARE形成四螺旋束，拉近两膜","B. v-SNARE与t-SNARE形成二螺旋束，拉近两膜","C. v-SNARE与Rab蛋白形成四螺旋束，拉近两膜","D. t-SNARE与Rab效应器形成四螺旋束，拉近两膜"],"a":"A","e":"SNARE蛋白通过v-SNARE与t-SNARE形成四螺旋束，拉近两膜从而催化融合。","oe":["v-SNARE与t-SNARE形成反式四螺旋束，拉近两膜从而催化融合。","SNARE复合物为四螺旋束而非二螺旋束，此项数目错误。","Rab参与小泡停靠，不与v-SNARE形成四螺旋束催化融合。","Rab效应器负责锚定，不与t-SNARE形成四螺旋束催化融合。"]},"cards":[{"front":"SNARE蛋白催化什么反应？如何实现？","back":"催化膜泡运输中的膜融合；v-SNARE与t-SNARE形成四螺旋束，拉近两膜","mnemonic":"四螺旋束拉链，两膜贴紧","type":"功能","useImg":true,"blank":"膜融合","blank2":"v-SNARE与t-SNARE形成四螺旋束"}]},{"i":17,"sec":"第七节 停靠融合","title":"SNARE引导运输 (p42)","notes":"The role of SNAREs in guiding vesicular transport：从ER衍生的膜泡上的v-SNARE与靶膜(高尔基体)上特异的t-SNARE配对，保证小泡只与正确靶膜融合。\n\n【本页英文讲解】\n本页说明SNARE在引导膜泡运输中的作用。来自内质网（ER）的膜泡上的v-SNARE，与靶膜即高尔基体上特异的t-SNARE相互配对，从而保证小泡只与正确的靶膜发生融合。这种v-SNARE与t-SNARE的配对特异性，正是膜泡运输方向性和准确性的分子基础。考点：SNARE配对具有特异性，与Rab的定向作用协同完成精确投递。","page":42,"level":"掌握","img":"assets/img/ch04/p042.jpg","anim":"snare_specificity","fig":"SNARE 引导囊泡运输：从 ER 出芽的小泡带 v-SNARE，与 Golgi CGN 上的 t-SNARE 互补配对，而不是与溶酶体膜上的 SNARE 配对。图强调“v-/t-SNARE 各具特异性”，保证方向专一。","points":null,"check":{"q":"SNARE在膜泡运输中引导运输特异性的方式是？","o":["A. 从ER衍生的膜泡上的v-SNARE与靶膜上特异的t-SNARE配对","B. 从ER衍生的膜泡上的t-SNARE与靶膜上特异的v-SNARE配对","C. 从ER衍生的膜泡上的Rab与靶膜上特异的SNARE配对","D. 从ER衍生的膜泡上的包被蛋白与靶膜上特异的t-SNARE配对"],"a":"A","e":"v-SNARE与靶膜上特异t-SNARE配对，保证小泡只与正确靶膜融合。","oe":["小泡的v-SNARE与靶膜上特异的t-SNARE配对，保证融合特异性。","方向颠倒，v-SNARE在小泡上、t-SNARE在靶膜上。","Rab与SNARE属不同蛋白家族，二者不相互配对。","包被蛋白不参与SNARE配对，且融合前小泡须先脱包被。"]},"cards":[{"front":"SNARE如何保证小泡只与正确靶膜融合？","back":"ER衍生膜泡的v-SNARE与高尔基体特异t-SNARE配对；配对特异保证定向融合","mnemonic":"钥匙配锁，专膜专融","type":"流程","useImg":false,"blank":"t-SNARE","blank2":"高尔基体特异t-SNARE"}]},{"i":18,"sec":"第七节 停靠融合","title":"脱包被后融合 (p43)","notes":"After being released and shedding its coat, a vesicle fuses with its target——小泡释放并脱去包被后，与靶膜融合。包被脱去是融合的前提。\n\n【本页英文讲解】\n本页讲解小泡脱包被后的融合。小泡从供体膜释放并脱去包被（shedding its coat）后，才能与靶膜（target membrane）融合。脱包被是融合发生的前提，因为包被蛋白会阻碍膜之间的接触；网格蛋白有被小泡也需在脱包被后才能与靶膜作用。考点：包被的组装与脱除具有时序性，脱包被步骤是膜融合的必要条件。","page":43,"level":"掌握","img":"assets/img/ch04/p043.jpg","anim":null,"fig":"包被小泡出芽与脱包被后与靶膜融合：融合需要 v-SNARE 与 t-SNARE 相互作用。图对比“有包被的出芽”与“脱包被后的融合”两个阶段，强调 SNARE 介导的是后者。","points":null,"check":{"q":"小泡与靶膜融合的前提条件是？","o":["A. 小泡释放并脱去包被","B. 小泡保留包被","C. 小泡先与溶酶体融合","D. 小泡先合成新的SNARE"],"a":"A","e":"小泡释放并脱去包被后，才能与靶膜融合，包被脱去是融合的前提。","oe":["小泡释放并脱去包被后暴露SNARE，才能与靶膜发生融合。","保留包被会阻碍SNARE配对，小泡无法与靶膜融合。","小泡与靶膜融合前无需先与溶酶体融合。","SNARE已存在于小泡表面，融合前无需重新合成SNARE。"]},"cards":[{"front":"小泡与靶膜融合的前提是什么？","back":"小泡释放并脱去包被；脱包被后才与靶膜融合","mnemonic":"先脱衣，再进门","type":"流程","useImg":false,"blank":"脱去包被","blank2":"脱包被"}]},{"i":19,"sec":"第七节 停靠融合","title":"膜融合需要胞质蛋白 (p44)","notes":"一旦转运小泡识别靶膜并停泊，下一步涉及小泡膜与细胞器膜的融合，把物质交到细胞器内部。其中需要一些细胞质蛋白(如NSF、SNAP)参与融合。","page":44,"level":"掌握","img":"assets/img/ch04/p044.jpg","anim":null,"fig":"小泡与靶膜融合需要细胞质蛋白(融合蛋白)参与，克服能量障碍。正常情况下细胞膜不能自发融合，必须由融合蛋白催化。图说明“融合不是自发过程”。","points":null,"check":null,"cards":[{"front":"小泡停泊后融合需要哪些胞质蛋白参与？","back":"需要细胞质蛋白如NSF、SNAP参与；完成小泡膜与细胞器膜融合，把物质送入细胞器内部","mnemonic":"NSF、SNAP助融合","type":"组成","useImg":false,"blank":"NSF","blank2":"SNAP"}]},{"i":20,"sec":"第七节 停靠融合","title":"停靠融合的成分 (p45)","notes":"参与小泡和靶膜停靠和膜融合的成分：Rab GTPases控制小泡在靶膜的停靠；SNARE介导融合；NSF/SNAP等参与。\n\n【本页英文讲解】\n本页总结参与小泡与靶膜停靠及膜融合的成分：Rab GTP酶控制小泡在靶膜上的停靠（docking）；SNARE介导融合（fusion）；此外还有NSF、SNAP等蛋白参与，NSF/SNAP可催化SNARE复合物的解离以便循环利用。这些成分协同保证运输的特异性。考点：正确区分各成分功能，Rab负责停靠、SNARE负责融合、NSF/SNAP负责解离循环。","page":45,"level":"掌握","img":"assets/img/ch04/p045.jpg","anim":null,"fig":"参与停靠和融合的成分：①Rab GTPase——控制停靠；②SNARE——SNAP 受体，v-/t 两型；③NSF——N-乙基顺丁烯二酰亚胺敏感融合蛋白；④SNAP——可溶性 NSF 附着蛋白。动物细胞至少有 35 种 SNARE。","points":null,"check":null,"cards":[{"front":"控制小泡在靶膜停靠的关键分子是什么？","back":"Rab GTPases（Rab蛋白）；结合GTP时活性形式，介导小泡与靶膜停靠","mnemonic":"Rab=Rabbit，把泡\"停\"在靶膜上","type":"功能","useImg":true,"blank":"Rab GTPases","blank2":"Rab蛋白"},{"front":"介导小泡与靶膜膜融合的核心蛋白是什么？","back":"SNARE蛋白；v-SNARE与t-SNARE配对介导融合；NSF/SNAP参与融合后解离","mnemonic":"SNARE=绳结，把两膜\"绑\"在一起融合","type":"功能","useImg":true,"blank":"SNARE蛋白","blank2":"v-SNARE与t-SNARE配对"}]},{"i":21,"sec":"第七节 停靠融合","title":"停靠与融合两步 (p46)","notes":"①识别、停靠锚定：运输小泡-Rab-GTP ⇌ 靶膜上的Rab effector；②进一步识别、融合：运输小泡v-SNARE ⇌ 靶膜t-SNARE。两步保证特异性。\n\n【本页英文讲解】\n本页概括停靠与融合的两步机制：第一步为识别、停靠与锚定，运输小泡上的Rab-GTP与靶膜上的Rab效应因子（Rab effector）相互作用；第二步为进一步识别与融合，运输小泡的v-SNARE与靶膜的t-SNARE配对。二者层层校验，保证膜泡运输的高度特异性。考点：掌握Rab与SNARE在两个步骤中的先后分工及其对特异性的贡献。","page":46,"level":"掌握","img":"assets/img/ch04/p046.jpg","anim":"docking_fusion_steps","fig":null,"points":null,"check":{"q":"停靠与融合两步中，第一步识别、停靠锚定主要依赖？","o":["A. 运输小泡-Rab-GTP与靶膜上的Rab effector","B. 运输小泡v-SNARE与靶膜t-SNARE","C. 运输小泡包被蛋白与靶膜Rab effector","D. 运输小泡t-SNARE与靶膜v-SNARE"],"a":"A","e":"第一步是运输小泡-Rab-GTP与靶膜上的Rab effector识别、停靠锚定。","oe":["第一步由运输小泡Rab-GTP与靶膜上的Rab效应器识别、停靠锚定。","v-SNARE与t-SNARE配对属第二步膜融合，不是停靠锚定。","包被蛋白不识别Rab效应器，且停靠前小泡已脱包被。","方向错误，t-SNARE位于靶膜、v-SNARE位于小泡。"]},"cards":[{"front":"小泡停靠与融合分哪两步？","back":"①识别停靠锚定：小泡Rab-GTP与靶膜Rab effector结合；②识别融合：v-SNARE与t-SNARE配对","mnemonic":"先Rab停靠，后SNARE融合","type":"流程","useImg":true,"blank":"Rab effector","blank2":"Rab-GTP"},{"front":"为什么小泡运输具有高度特异性？","back":"两步识别保证：Rab-Rab effector配对决定停靠位点；v-SNARE/t-SNARE配对决定融合，双重校验","mnemonic":"双保险：Rab认门，SNARE开锁","type":"流程","useImg":false,"blank":"v-SNARE/t-SNARE","blank2":"Rab-Rab effector配对"}]},{"i":22,"sec":"第七节 停靠融合","title":"v-SNARE/t-SNARE融合 (p47)","notes":"v-SNARE与t-SNARE停靠和融合示意图：v-SNARE与t-SNARE缠绕形成反式SNARE复合物，拉近两膜，驱动膜融合。\n\n【本页英文讲解】\n本页以示意图展示v-SNARE与t-SNARE介导的停靠和融合：v-SNARE与t-SNARE相互缠绕，形成反式SNARE复合物（trans-SNARE complex），把小泡膜与靶膜拉近，进而驱动膜融合。融合后复合物转为顺式（cis），需NSF/SNAP解离以循环使用。考点：理解反式与顺式SNARE复合物的区别，以及SNARE拉链式缠绕驱动融合的机制。","page":47,"level":"理解","img":"assets/img/ch04/p047.jpg","anim":"docking_fusion_overview","fig":"停靠与融合总图：①VAMP(v-SNARE)+Rab-GTP+Rab effector 使小泡停靠；②Syntaxin(t-SNARE)+SNAP-25 与小泡 VAMP 组装 SNARE 复合体；③膜融合；④NSF+α-SNAP+ATP 水解驱动 SNARE 复合体解离。图右侧是 SNARE 复合体的螺旋束结构。","points":["停靠：VAMP(v-SNARE)+Rab-GTP；组装：Syntaxin(t-SNARE)+SNAP-25；融合后 NSF/α-SNAP/ATP 解离 SNARE 复合体。"],"check":null,"cards":null}],"mcq":[{"id":"ch04_mcq_13","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"LDL颗粒的核心成分是？","o":["A. 胆固醇酯","B. 载脂蛋白","C. 磷脂","D. 甘油三酯"],"a":"A","e":"LDL核心为约1500分子胆固醇酯，外壳为磷脂、胆固醇和载脂蛋白B。","kp":"ch04_s1_20"},{"id":"ch04_mcq_14","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"SNARE蛋白的功能是？","o":["A. 催化膜融合","B. 组装网格蛋白","C. 水解ATP","D. 合成脂类"],"a":"A","e":"SNARE蛋白催化膜泡运输中的膜融合反应：v-SNARE与t-SNARE形成四螺旋束，拉近两膜。","kp":"ch04_s1_11"},{"id":"ch04_mcq_15","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"小泡运输中货物蛋白的定向依靠？","o":["A. 随机扩散","B. 货物蛋白信号序列与受体特异相互作用","C. 膜电位","D. 温度"],"a":"B","e":"Targeting sequences on cargo proteins make specific molecular interactions——货物蛋白信号序列与受体特异作用保证正确定向。","kp":"ch04_s1_10"},{"id":"ch04_mcq_16","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"参与小泡和靶膜停靠的成分是？","o":["A. Rab GTPase","B. 网格蛋白","C. Sar","D. COPI"],"a":"A","e":"Rab GTPases控制小泡在靶膜的识别、锚定、停靠；SNARE介导融合。","kp":"ch04_s1_20"},{"id":"ch04_mcq_17","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"COPI小泡的包被装配依赖于？","o":["A. ARF(GTP结合蛋白)","B. Sar","C. dynamin","D. clathrin"],"a":"A","e":"COPI有7个蛋白亚基及ARF(类似COPII的Sar)，包被复合物装配/去装配依赖ARF。","kp":"ch04_s1_6"},{"id":"ch04_mcq_18","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"网格蛋白三脚复合体(triskelion)由什么组成？","o":["A. 3条重链+3条轻链","B. 6条重链","C. 3条重链","D. 1条肽链"],"a":"A","e":"网格蛋白由3条重链和3条轻链组成三脚蛋白复合体(triskelion)，组装成网格包被。","kp":"ch04_s1_7"},{"id":"ch04_mcq_19","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"胞吞途径中,质膜物质经胞内体最终到达？","o":["A. 内质网","B. 溶酶体","C. 细胞核","D. 线粒体"],"a":"B","e":"Endocytic pathway：质膜→早期胞内体→晚期胞内体→溶酶体，进行降解。","kp":"ch04_s1_7"},{"id":"ch04_mcq_20","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"下列属于翻译后转移的是？","o":["A. 分泌蛋白入ER","B. 线粒体蛋白的导入","C. 溶酶体酶入溶酶体","D. 膜蛋白入质膜"],"a":"B","e":"翻译后转移：蛋白在游离核糖体合成后转运至线粒体、叶绿体、过氧化物酶体等。分泌蛋白入ER是共翻译转移。","kp":"ch04_s1_12"},{"id":"ch04_mcq_21","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"膜融合时,小泡首先需要？","o":["A. 脱去包被","B. 保留包被","C. 增大体积","D. 改变pH"],"a":"A","e":"After being released and shedding its coat, a vesicle fuses with its target——小泡脱去包被后才能与靶膜融合。","kp":"ch04_s1_19"},{"id":"ch04_mcq_22","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"调节性分泌与组成型分泌的区别在于？","o":["A. 是否需信号触发","B. 是否需高尔基体","C. 是否需ATP","D. 是否需核糖体"],"a":"A","e":"组成型分泌持续进行；调节性分泌需信号(如激素、神经递质)触发小泡与质膜融合释放。","kp":"ch04_s1_6"},{"id":"ch04_mcq_23","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"转铁蛋白循环的功能是？","o":["A. 运输铁","B. 运输胆固醇","C. 运输葡萄糖","D. 运输水"],"a":"A","e":"转铁蛋白结合铁，经受体介导胞吞进入细胞释放铁，受体和转铁蛋白回收循环，存在于所有生长的哺乳动物细胞。","kp":"ch04_s1_1"},{"id":"ch04_mcq_24","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"Rab效应器(Rab effector)位于？","o":["A. 靶膜","B. 小泡内","C. 细胞核","D. 线粒体"],"a":"A","e":"运输小泡-Rab-GTP与靶膜上的Rab effector结合，实现识别与停靠锚定。","kp":"ch04_s1_14"},{"id":"ch04_mcq_25","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"蛋白质分选信号序列的特点是？","o":["A. 随机序列","B. 特定氨基酸序列,引导蛋白到正确部位","C. 只有糖链","D. 由膜脂决定"],"a":"B","e":"信号序列(如信号肽、KDEL、NLS、M6P)是特定的氨基酸序列，作为蛋白质分选的'邮政编码'。","kp":"ch04_s1_10"}],"judge":[{"id":"ch04_judge_2","modI":1,"q":"COPII小泡负责从高尔基体到内质网的逆向运输。","a":"错","e":"COPII负责ER→Golgi顺行运输；COPI负责Golgi→ER的逆向回收。","kp":"ch04_s1_0"},{"id":"ch04_judge_5","modI":1,"q":"ER驻留蛋白C端的回收信号是KDEL。","a":"对","e":"Bip、PDI等ER驻留蛋白含C端KDEL信号，逃逸后经COPI小泡回收回ER。","kp":"ch04_s1_5"},{"id":"ch04_judge_6","modI":1,"q":"v-SNARE位于靶膜上，t-SNARE位于运输小泡上。","a":"错","e":"v-SNARE在运输小泡上，t-SNARE在靶膜上，二者互补配对介导膜融合。","kp":"ch04_s1_15"},{"id":"ch04_judge_7","modI":1,"q":"Rab蛋白属于GTP酶超家族的开关蛋白，控制小泡的识别、锚定和停靠。","a":"对","e":"Rab是GTP酶超家族开关蛋白，高度选择性地分布于不同膜，控制小泡停靠。","kp":"ch04_s1_12"}],"fill":[{"id":"ch04_fill_2","modI":1,"q":"COPII小泡负责________运输；COPI小泡负责________运输；网格蛋白小泡负责TGN→质膜/溶酶体及________。","a":"ER→Golgi(顺行),Golgi→ER(回收),受体介导的胞吞","kp":"ch04_s1_0"},{"id":"ch04_fill_5","modI":1,"q":"COPII组装依赖GTP结合蛋白________；COPI组装依赖________；胞吞掐断依赖________。","a":"Sar,ARF,dynamin","kp":"ch04_s1_1"},{"id":"ch04_fill_6","modI":1,"q":"ER驻留蛋白C端的回收信号是________,逃逸后经________小泡回收回ER。","a":"KDEL,COPI","kp":"ch04_s1_5"},{"id":"ch04_fill_7","modI":1,"q":"囊泡停靠中,________(小G蛋白)控制小泡的识别、锚定、停靠；________介导膜融合。","a":"Rab,v-SNARE/t-SNARE","kp":"ch04_s1_8"},{"id":"ch04_fill_10","modI":1,"q":"v-SNARE位于________,t-SNARE位于________,二者互补配对介导融合。","a":"运输小泡,靶膜","kp":"ch04_s1_22"},{"id":"ch04_fill_12","modI":1,"q":"膜泡运输的方向由________决定；Rab高度选择性地分布于不同膜,成为膜的________标志。","a":"包被蛋白,身份(分子)","kp":"ch04_s1_13"}],"short":[{"id":"ch04_short_3","modI":1,"q":"简述小泡运输的停靠和融合机制。","a":"小泡运输的停靠和融合：\n\n【停靠(docking)】\n①Rab蛋白(小G蛋白，60多种)高度选择性地分布在特定膜上，是膜身份的分子标志；\n②运输小泡-Rab-GTP与靶膜上的Rab effector结合，实现识别、锚定、停靠。\n\n【融合(fusion)】\n①小泡脱去包被；\n②小泡表面的v-SNARE与靶膜上的t-SNARE互补配对，形成反式SNARE复合物；\n③SNARE缠绕拉近两膜，NSF/SNAP等胞质蛋白参与，驱动膜融合；\n④小泡内容物释放到靶细胞器内。\n\n【分工】\nRab引导小泡到正确靶膜；SNARE介导膜融合。\n\n【意义】\n保证小泡只与正确的靶膜融合，实现货物精准投递。2013年诺贝尔奖授予相关发现。","kp":"ch04_s1_8"},{"id":"ch04_short_5","modI":1,"q":"简述蛋白质分选的类型及信号。","a":"蛋白质分选(protein sorting)：\n\n【按转移时间分类】\n①共翻译转移(co-translational)：蛋白在游离核糖体起始合成后，边翻译边经信号肽引导进入rER(如分泌蛋白、膜蛋白、溶酶体酶)；\n②翻译后转移(post-translational)：蛋白在游离核糖体完全合成后转运至线粒体、叶绿体、过氧化物酶体、细胞核。\n\n【按运输途径分类】\n①膜泡运输(内膜系统)；②跨膜运输(线粒体/叶绿体/过氧化物酶体)；③核孔运输(细胞核)。\n\n【分选信号】\n①信号肽(signal peptide)——N端引导入ER；\n②信号斑(signal patch)——由折叠形成的空间信号；\n③KDEL——ER驻留信号；\n④NLS/NES——核定位/核输出信号；\n⑤M6P——溶酶体分选信号；\n⑥导肽/转运肽——线粒体/叶绿体。\n\n【意义】\n信号序列是蛋白质分选的'邮政编码'，保证蛋白到达正确部位。","kp":"ch04_s1_10"}],"calc":[{"id":"ch04_calc_2","modI":1,"q":"论述内膜系统蛋白质分选的三条途径及其分子机制。","a":"蛋白质分选有三条途径:膜泡运输、跨膜运输、核孔运输","steps":"【1. 膜泡运输(内膜系统)】\n①共翻译转移：信号肽引导新生肽入ER→经COPII到Golgi→再分选；\n②COPI回收逃逸蛋白(KDEL信号)；\n③网格蛋白小泡运往质膜/溶酶体；\n④溶酶体酶经M6P途径分选。\n\n【2. 跨膜运输(线粒体/叶绿体/过氧化物酶体)】\n①翻译后转移：蛋白在游离核糖体合成；\n②N端导肽/转运肽引导，与膜受体识别；\n③在膜接触点经转运子(TOM/TIM)跨膜进入；\n④导肽被切除，蛋白折叠。\n\n【3. 核孔运输(细胞核)】\n①亲核蛋白含核定位信号(NLS)；\n②NLS与输入蛋白importin结合；\n③经核孔复合体(NPC)入核；\n④Ran-GTP调控货物释放；\n⑤核输出信号(NES)介导出核。\n\n【共同点】\n都依赖蛋白质自身的信号序列；都需受体识别；都消耗能量(GTP/ATP)。\n\n【意义】\n保证每种蛋白到达正确部位，维持细胞区室化。","kp":"ch04_s1_4"}],"term":[{"id":"ch04_term_2","modI":1,"term":"COPII有被小泡","def":"①负责从内质网到高尔基体顺行运输的小泡（定义）。②组装：GTP结合蛋白Sar-GTP结合ER膜，诱导COPII蛋白亚单位(Sec23/Sec24等)组装（机制）。③功能：ER→Golgi运输（功能）。","kps":"踩分点:①定义(1分)②Sar依赖(1分)③功能(1分)","kp":"ch04_s1_0"},{"id":"ch04_term_3","modI":1,"term":"COPI有被小泡","def":"①负责回收ER逃逸蛋白返回ER的小泡（定义）。②组成：7个蛋白亚基+ARF(GTP结合蛋白)（组成）。③功能：Golgi→ER逆向运输、回收驻留蛋白（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)","kp":"ch04_s1_0"},{"id":"ch04_term_7","modI":1,"term":"Rab蛋白","def":"①GTP酶超家族的开关蛋白，60多种（定义）。②特点：高度选择性地分布在特定膜上，是膜身份的分子标志（特点）。③功能：控制转运小泡在靶膜的识别、锚定、停靠（功能）。","kps":"踩分点:①定义(1分)②特点(1分)③功能(2分)","kp":"ch04_s1_12"},{"id":"ch04_term_8","modI":1,"term":"SNARE蛋白","def":"①介导膜泡与靶膜融合的蛋白家族（定义）。②分类：v-SNARE(小泡上)、t-SNARE(靶膜上)（分类）。③机制：v-SNARE与t-SNARE互补配对形成反式SNARE复合物，拉近两膜驱动融合（机制）。④意义：保证小泡只与正确靶膜融合；2013年诺贝尔奖（意义）。","kps":"踩分点:①定义(1分)②分类(1分)③机制(1分)④意义(1分)","kp":"ch04_s1_11"},{"id":"ch04_term_9","modI":1,"term":"KDEL回收信号","def":"①ER驻留蛋白C端的一段回收信号序列(KDEL)（定义）。②功能：使Bip、PDI等驻留蛋白被保留在ER中（功能）。③机制：逃逸到高尔基体的驻留蛋白被KDEL受体识别，经COPI小泡回收回ER（机制）。","kps":"踩分点:①定义(1分)②功能(1分)③机制(2分)","kp":"ch04_s1_5"},{"id":"ch04_term_10","modI":1,"term":"共翻译转移(Cotranslational Translocation)","def":"①蛋白质在游离核糖体起始合成后，边翻译边经信号肽引导进入ER的过程（定义）。②机制：信号肽-SRP-核糖体复合物结合ER膜SRP受体→共翻译转移入ER腔（机制）。③对象：分泌蛋白、膜蛋白、溶酶体酶（对象）。","kps":"踩分点:①定义(1分)②机制(1分)③对象(1分)","kp":"ch04_s1_16"},{"id":"ch04_term_11","modI":1,"term":"翻译后转移(Post-translational Translocation)","def":"①蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器的过程（定义）。②对象：线粒体、叶绿体、过氧化物酶体、细胞核蛋白（对象）。③特点：需N端导肽/转运肽引导，需解折叠（特点）。","kps":"踩分点:①定义(1分)②对象(2分)③特点(1分)","kp":"ch04_s1_16"},{"id":"ch04_term_14","modI":1,"term":"膜融合(Membrane Fusion)","def":"①运输小泡与靶膜脂双层合并、内容物释放的过程（定义）。②机制：v-SNARE与t-SNARE配对形成反式复合物，拉近两膜；NSF/SNAP等参与（机制）。③前提：小泡脱去包被（前提）。","kps":"踩分点:①定义(1分)②机制(2分)③前提(1分)","kp":"ch04_s1_16"},{"id":"ch04_term_15","modI":1,"term":"组成型分泌与调节型分泌","def":"①组成型分泌：小泡持续与质膜融合、不断分泌（定义）。②调节型分泌：小泡储存于胞内，需信号(激素/神经递质)触发才与质膜融合释放（定义）。③意义：调节型分泌实现信号的精确调控(如神经递质释放)（意义）。","kps":"踩分点:①组成型(1分)②调节型(2分)③意义(1分)","kp":"ch04_s1_6"}]}],"mcq":[{"id":"ch04_mcq_1","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"蛋白质输入细胞器不包括下列哪种途径？","o":["A. 囊泡运输","B. 跨膜运输","C. 核孔运输","D. 简单扩散"],"a":"D","e":"蛋白质输入细胞器3途径：囊泡运输(内膜系统)、跨膜运输(线粒体/叶绿体/过氧化物酶体)、核孔运输(细胞核)。蛋白质是大分子，不能简单扩散。","kp":"ch04_s0_0","oe":["囊泡运输是蛋白质输入内膜系统细胞器的途径之一，属其范畴。","跨膜运输是蛋白进入线粒体、叶绿体等的途径之一。","核孔运输是蛋白质进入细胞核的途径之一，属输入细胞器。","蛋白质是大分子，不能以简单扩散方式进入细胞器。"]},{"id":"ch04_mcq_2","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"2013年诺贝尔生理学或医学奖授予？","o":["A. 囊泡运输调节机制","B. 水通道","C. RNAi","D. 泛素降解"],"a":"A","e":"2013年诺贝尔奖授予Rothman、Schekman、Südhof，发现细胞囊泡运输的调节机制。","kp":"ch04_s0_4","oe":["2013年诺贝尔奖授予囊泡运输调节机制，获奖者为Rothman等。","水通道研究获2003年诺贝尔化学奖，与2013年生理学或医学奖无关。","RNAi相关研究获2006年诺贝尔奖，非2013年。","泛素介导的蛋白降解获2004年诺贝尔化学奖，非2013年。"]},{"id":"ch04_mcq_3","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"负责ER→高尔基体顺行运输的小泡是？","o":["A. COPII","B. COPI","C. 网格蛋白小泡","D. 溶酶体"],"a":"A","e":"COPII小泡负责ER→Golgi顺行运输；COPI小泡负责Golgi→ER逆向回收；网格蛋白小泡负责TGN→质膜/溶酶体及胞吞。","kp":"ch04_s0_6","oe":["COPII小泡负责ER→高尔基体的顺行运输。","COPI小泡负责高尔基体到ER的逆向回收，非顺行。","网格蛋白小泡负责TGN→质膜或溶酶体运输及胞吞。","溶酶体是细胞器而非运输小泡，不负责顺行运输。"]},{"id":"ch04_mcq_4","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"负责回收逃逸蛋白返回ER的小泡是？","o":["A. COPII","B. COPI","C. 网格蛋白","D. 核孔"],"a":"B","e":"COPI小泡负责回收、转运ER逃逸蛋白返回ER，含7个亚基和ARF(GTP结合蛋白)。","kp":"ch04_s0_9","oe":["COPII负责ER→高尔基体顺行运输，不回收逃逸蛋白。","COPI含ARF，负责回收逃逸蛋白返回ER。","网格蛋白小泡参与TGN出芽和胞吞，不回收ER逃逸蛋白。","核孔是核质交换通道，与ER逃逸蛋白回收无关。"]},{"id":"ch04_mcq_5","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"网格蛋白有被小泡的组成不包括？","o":["A. 网格蛋白","B. 衔接蛋白AP","C. 发动蛋白Dynamin","D. Sar蛋白"],"a":"D","e":"Sar蛋白参与COPII组装；网格蛋白小泡由网格蛋白+衔接蛋白AP+发动蛋白dynamin组成。","kp":"ch04_s0_9","oe":["网格蛋白是小泡外壳的主要成分，属于其组成。","衔接蛋白AP连接网格蛋白与货物受体，属于其组成。","发动蛋白dynamin参与小泡掐断，属于其组成。","Sar蛋白参与COPII小泡组装，不属于网格蛋白小泡。"]},{"id":"ch04_mcq_6","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"发动蛋白(dynamin)的功能是？","o":["A. 组装网格蛋白","B. 提供能量、引起环收缩,将小泡从膜上掐下来","C. 识别货物","D. 催化融合"],"a":"B","e":"dynamin是小GTP蛋白，在胞吞中提供能量、引起环收缩，将小泡从膜上掐断。","kp":"ch04_s0_16","oe":["组装网格蛋白由网格蛋白自身及AP完成，非dynamin功能。","dynamin是GTP酶，提供能量引起环收缩，将小泡从膜上掐断。","识别货物由货物受体与衔接蛋白负责，非dynamin。","催化膜融合由SNARE完成，非dynamin功能。"]},{"id":"ch04_mcq_7","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"家族性高胆固醇血症的分子基础是？","o":["A. LDL受体基因缺失或无功能","B. 胆固醇过多","C. 网格蛋白过多","D. SRP缺陷"],"a":"A","e":"LDL受体基因缺失或受体无功能→胆固醇摄入通路阻断→细胞不能摄取胆固醇→血胆固醇升高。","kp":"ch04_s0_22","oe":["LDL受体基因缺失或无功能，细胞不能摄取胆固醇，血胆固醇升高。","胆固醇过多是疾病的结果表现，并非分子基础。","网格蛋白过多与家族性高胆固醇血症无直接关系。","SRP缺陷影响分泌蛋白共翻译转运，与此病分子基础无关。"]},{"id":"ch04_mcq_8","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"ER驻留蛋白逃逸后如何被回收？","o":["A. 经KDEL信号被受体识别,由COPI小泡回收","B. 直接降解","C. 分泌到胞外","D. 变成膜蛋白"],"a":"A","e":"ER驻留蛋白C端含KDEL回收信号，逃逸到高尔基体后被KDEL受体识别，经COPI小泡回收回ER。","kp":"ch04_s0_23","oe":["ER驻留蛋白C端KDEL被受体识别，经COPI小泡回收回ER。","逃逸蛋白会被回收而非直接降解。","逃逸蛋白不会分泌到胞外，而会被受体识别回收。","逃逸蛋白不会变成膜蛋白，仍随COPI小泡返回ER。"]},{"id":"ch04_mcq_9","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"Rab蛋白属于？","o":["A. GTP酶超家族的开关蛋白","B. 网格蛋白","C. 衔接蛋白","D. 蛋白酶"],"a":"A","e":"Rab属于GTP酶超家族的开关蛋白，有60多种，高度选择性地分布在不同膜上，控制小泡停靠。","kp":"ch04_s0_0","oe":["Rab属于GTP酶超家族的开关蛋白，控制小泡停靠。","网格蛋白是构成包被的结构蛋白，与Rab不同。","衔接蛋白连接网格蛋白与货物受体，不是Rab。","蛋白酶负责降解蛋白质，Rab是GTP酶，二者不同。"]},{"id":"ch04_mcq_10","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"v-SNARE与t-SNARE的关系是？","o":["A. 都位于同一膜","B. v-SNARE在小泡、t-SNARE在靶膜,互补配对介导融合","C. 都是网格蛋白","D. 都是Rab"],"a":"B","e":"v-SNARE在小泡表面、t-SNARE在靶膜上，两者互补配对形成反式SNARE复合物，介导膜融合。","kp":null,"oe":["v-SNARE在小泡上、t-SNARE在靶膜上，并不位于同一膜。","v-SNARE在小泡、t-SNARE在靶膜，互补配对介导膜融合。","SNARE与网格蛋白是不同蛋白，功能各异。","SNARE与Rab属不同蛋白家族，不能混为一类。"]},{"id":"ch04_mcq_11","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"COPII小泡组装依赖的GTP结合蛋白是？","o":["A. Sar","B. ARF","C. Rab","D. Dynamin"],"a":"A","e":"Sar-GTP结合ER膜，诱导COPII蛋白亚单位组装。COPI依赖ARF，网格蛋白胞吞依赖dynamin。","kp":"ch04_s0_8","oe":["Sar-GTP结合ER膜，诱导COPII蛋白亚单位组装。","ARF参与COPI包被装配，不组装COPII小泡。","Rab控制小泡停靠，不参与COPII组装。","Dynamin参与胞吞小泡从质膜掐断，与COPII无关。"]},{"id":"ch04_mcq_12","mod":"模块一：运输途径与网格蛋白小泡","modI":0,"q":"受体介导的胞吞作用中,负责将小泡从膜上掐断的是？","o":["A. 网格蛋白","B. 发动蛋白dynamin","C. 衔接蛋白","D. SNARE"],"a":"B","e":"dynamin在小泡颈部形成环并收缩，消耗GTP将小泡从质膜上掐断。","kp":"ch04_s0_14","oe":["网格蛋白构成小泡外壳，不负责将小泡从膜上掐断。","dynamin在小泡颈部形成环并消耗GTP，将小泡从质膜掐断。","衔接蛋白连接网格蛋白与受体，不负责掐断。","SNARE介导膜融合，不负责小泡从膜上掐断。"]},{"id":"ch04_mcq_13","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"LDL颗粒的核心成分是？","o":["A. 胆固醇酯","B. 载脂蛋白","C. 磷脂","D. 甘油三酯"],"a":"A","e":"LDL核心为约1500分子胆固醇酯，外壳为磷脂、胆固醇和载脂蛋白B。","kp":"ch04_s1_20","oe":["LDL核心为约1500分子胆固醇酯。","载脂蛋白B位于LDL外壳，不是核心成分。","磷脂位于LDL外壳，不是核心主要成分。","甘油三酯不是LDL核心的主要成分，核心为胆固醇酯。"]},{"id":"ch04_mcq_14","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"SNARE蛋白的功能是？","o":["A. 催化膜融合","B. 组装网格蛋白","C. 水解ATP","D. 合成脂类"],"a":"A","e":"SNARE蛋白催化膜泡运输中的膜融合反应：v-SNARE与t-SNARE形成四螺旋束，拉近两膜。","kp":"ch04_s1_11","oe":["SNARE通过v/t-SNARE形成四螺旋束拉近两膜，催化膜融合。","组装网格蛋白由网格蛋白与AP完成，与SNARE无关。","SNARE不水解ATP，其作用依赖蛋白构象变化。","合成脂类由相关酶催化，非SNARE蛋白的功能。"]},{"id":"ch04_mcq_15","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"小泡运输中货物蛋白的定向依靠？","o":["A. 随机扩散","B. 货物蛋白信号序列与受体特异相互作用","C. 膜电位","D. 温度"],"a":"B","e":"Targeting sequences on cargo proteins make specific molecular interactions——货物蛋白信号序列与受体特异作用保证正确定向。","kp":"ch04_s1_10","oe":["货物定向并非随机扩散，而是由特异信号决定。","货物蛋白信号序列与受体特异相互作用，保证正确定向。","膜电位不决定货物蛋白的定向运输。","温度影响运输速率，但不决定货物定向的特异性。"]},{"id":"ch04_mcq_16","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"参与小泡和靶膜停靠的成分是？","o":["A. Rab GTPase","B. 网格蛋白","C. Sar","D. COPI"],"a":"A","e":"Rab GTPases控制小泡在靶膜的识别、锚定、停靠；SNARE介导融合。","kp":"ch04_s1_20","oe":["Rab GTPase控制小泡在靶膜的识别、锚定和停靠。","网格蛋白构成小泡包被，与停靠识别无关。","Sar参与COPII小泡组装，不介导小泡与靶膜停靠。","COPI参与高尔基体逆向运输，不介导停靠。"]},{"id":"ch04_mcq_17","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"COPI小泡的包被装配依赖于？","o":["A. ARF(GTP结合蛋白)","B. Sar","C. dynamin","D. clathrin"],"a":"A","e":"COPI有7个蛋白亚基及ARF(类似COPII的Sar)，包被复合物装配/去装配依赖ARF。","kp":"ch04_s1_6","oe":["COPI含7个蛋白亚基，其包被装配依赖ARF（GTP结合蛋白）。","Sar参与COPII包被组装，不参与COPI。","dynamin参与网格蛋白小泡从膜上掐断，非COPI装配。","clathrin构成网格蛋白小泡外壳，与COPI无关。"]},{"id":"ch04_mcq_18","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"网格蛋白三脚复合体(triskelion)由什么组成？","o":["A. 3条重链+3条轻链","B. 6条重链","C. 3条重链","D. 1条肽链"],"a":"A","e":"网格蛋白由3条重链和3条轻链组成三脚蛋白复合体(triskelion)，组装成网格包被。","kp":"ch04_s1_7","oe":["网格蛋白三脚复合体由3条重链和3条轻链组成。","含3条重链而非6条重链，且还含轻链。","除3条重链外还含3条轻链，仅说重链不完整。","三脚复合体由6条肽链组成，并非1条肽链。"]},{"id":"ch04_mcq_19","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"胞吞途径中,质膜物质经胞内体最终到达？","o":["A. 内质网","B. 溶酶体","C. 细胞核","D. 线粒体"],"a":"B","e":"Endocytic pathway：质膜→早期胞内体→晚期胞内体→溶酶体，进行降解。","kp":"ch04_s1_7","oe":["胞吞物质经胞内体最终到溶酶体降解，不会到内质网。","质膜物质经早期、晚期胞内体，最终到达溶酶体降解。","胞吞途径不经过细胞核，物质最终到达溶酶体降解。","胞吞途径不经过线粒体，物质最终到达溶酶体降解。"]},{"id":"ch04_mcq_20","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"下列属于翻译后转移的是？","o":["A. 分泌蛋白入ER","B. 线粒体蛋白的导入","C. 溶酶体酶入溶酶体","D. 膜蛋白入质膜"],"a":"B","e":"翻译后转移：蛋白在游离核糖体合成后转运至线粒体、叶绿体、过氧化物酶体等。分泌蛋白入ER是共翻译转移。","kp":"ch04_s1_12","oe":["分泌蛋白入ER是共翻译转移，不属于翻译后转移。","线粒体蛋白在游离核糖体合成后翻译后导入，属翻译后转移。","溶酶体酶经ER和高尔基体转运，属共翻译及囊泡运输。","膜蛋白入质膜经共翻译转运和囊泡运输，非翻译后转移。"]},{"id":"ch04_mcq_21","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"膜融合时,小泡首先需要？","o":["A. 脱去包被","B. 保留包被","C. 增大体积","D. 改变pH"],"a":"A","e":"After being released and shedding its coat, a vesicle fuses with its target——小泡脱去包被后才能与靶膜融合。","kp":"ch04_s1_19","oe":["小泡释放并脱去包被后暴露SNARE，才能与靶膜融合。","保留包被会阻碍SNARE配对，小泡无法与靶膜融合。","增大体积不是小泡与靶膜融合的前提条件。","改变pH不是膜融合的必要前提条件。"]},{"id":"ch04_mcq_22","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"调节性分泌与组成型分泌的区别在于？","o":["A. 是否需信号触发","B. 是否需高尔基体","C. 是否需ATP","D. 是否需核糖体"],"a":"A","e":"组成型分泌持续进行；调节性分泌需信号(如激素、神经递质)触发小泡与质膜融合释放。","kp":"ch04_s1_6","oe":["组成型分泌持续进行，调节性分泌需信号触发，区别在是否需信号。","两者都需经高尔基体转运，不是二者区别。","两者都需消耗能量即ATP，不是二者区别。","两者蛋白质都由核糖体合成，不是二者区别。"]},{"id":"ch04_mcq_23","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"转铁蛋白循环的功能是？","o":["A. 运输铁","B. 运输胆固醇","C. 运输葡萄糖","D. 运输水"],"a":"A","e":"转铁蛋白结合铁，经受体介导胞吞进入细胞释放铁，受体和转铁蛋白回收循环，存在于所有生长的哺乳动物细胞。","kp":"ch04_s1_1","oe":["转铁蛋白结合铁，经受体介导胞吞进入细胞并释放铁。","运输胆固醇的是LDL，不是转铁蛋白。","转铁蛋白不运输葡萄糖，葡萄糖由葡萄糖转运体运输。","运输水的是水通道蛋白，不是转铁蛋白。"]},{"id":"ch04_mcq_24","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"Rab效应器(Rab effector)位于？","o":["A. 靶膜","B. 小泡内","C. 细胞核","D. 线粒体"],"a":"A","e":"运输小泡-Rab-GTP与靶膜上的Rab effector结合，实现识别与停靠锚定。","kp":"ch04_s1_14","oe":["运输小泡Rab-GTP与靶膜上的Rab效应器结合，实现识别与停靠。","Rab效应器位于靶膜上，而非小泡内。","Rab效应器不在细胞核，与核无关。","Rab效应器不在线粒体，与线粒体无关。"]},{"id":"ch04_mcq_25","mod":"模块二：COP小泡与停靠融合","modI":1,"q":"蛋白质分选信号序列的特点是？","o":["A. 随机序列","B. 特定氨基酸序列,引导蛋白到正确部位","C. 只有糖链","D. 由膜脂决定"],"a":"B","e":"信号序列(如信号肽、KDEL、NLS、M6P)是特定的氨基酸序列，作为蛋白质分选的'邮政编码'。","kp":"ch04_s1_10","oe":["分选信号是特定序列而非随机序列。","信号序列是特定氨基酸序列，引导蛋白到正确部位。","信号序列本质是氨基酸序列，并非只有糖链。","信号由蛋白质序列决定，而非由膜脂决定。"]}],"judge":[{"id":"ch04_judge_1","modI":0,"q":"蛋白质输入细胞器有囊泡运输、跨膜运输和核孔运输三种途径。","a":"对","e":"三种途径：囊泡运输(内膜系统)、跨膜运输(线粒体/叶绿体/过氧化物酶体)、核孔运输(细胞核)。","kp":"ch04_s0_0"},{"id":"ch04_judge_2","modI":1,"q":"COPII小泡负责从高尔基体到内质网的逆向运输。","a":"错","e":"COPII负责ER→Golgi顺行运输；COPI负责Golgi→ER的逆向回收。","kp":"ch04_s1_0"},{"id":"ch04_judge_3","modI":0,"q":"网格蛋白由3条重链和3条轻链组成三脚复合体。","a":"对","e":"网格蛋白由3条重链和3条轻链组成三脚复合体(triskelion)，组装成网格包被。","kp":"ch04_s0_10"},{"id":"ch04_judge_4","modI":0,"q":"发动蛋白(dynamin)是一种小GTP蛋白，能将小泡从膜上掐断。","a":"对","e":"dynamin在胞吞小泡颈部形成环并收缩，消耗GTP将小泡从膜上掐断。","kp":"ch04_s0_16"},{"id":"ch04_judge_5","modI":1,"q":"ER驻留蛋白C端的回收信号是KDEL。","a":"对","e":"Bip、PDI等ER驻留蛋白含C端KDEL信号，逃逸后经COPI小泡回收回ER。","kp":"ch04_s1_5"},{"id":"ch04_judge_6","modI":1,"q":"v-SNARE位于靶膜上，t-SNARE位于运输小泡上。","a":"错","e":"v-SNARE在运输小泡上，t-SNARE在靶膜上，二者互补配对介导膜融合。","kp":"ch04_s1_15"},{"id":"ch04_judge_7","modI":1,"q":"Rab蛋白属于GTP酶超家族的开关蛋白，控制小泡的识别、锚定和停靠。","a":"对","e":"Rab是GTP酶超家族开关蛋白，高度选择性地分布于不同膜，控制小泡停靠。","kp":"ch04_s1_12"},{"id":"ch04_judge_8","modI":0,"q":"家族性高胆固醇血症的分子基础是LDL受体基因缺失或受体无功能。","a":"对","e":"LDL受体缺陷→胆固醇摄入通路阻断→血胆固醇升高。","kp":"ch04_s0_22"},{"id":"ch04_judge_9","modI":0,"q":"受体介导的胞吞作用中，LDL被降解而受体也随之被降解，不能回收。","a":"错","e":"LDL在溶酶体被降解，而受体可回收并循环利用。","kp":"ch04_s0_21"},{"id":"ch04_judge_10","modI":0,"q":"2013年诺贝尔生理学或医学奖授予发现细胞囊泡运输调节机制的科学家。","a":"对","e":"2013年授予Rothman、Schekman、Südhof，发现细胞囊泡运输的调节机制。","kp":"ch04_s0_4"}],"fill":[{"id":"ch04_fill_1","modI":0,"q":"蛋白质输入细胞器的3种途径是________、________和________。","a":"囊泡运输(膜泡运输),跨膜运输,核孔运输","kp":"ch04_s0_0"},{"id":"ch04_fill_2","modI":1,"q":"COPII小泡负责________运输；COPI小泡负责________运输；网格蛋白小泡负责TGN→质膜/溶酶体及________。","a":"ER→Golgi(顺行),Golgi→ER(回收),受体介导的胞吞","kp":"ch04_s1_0"},{"id":"ch04_fill_3","modI":0,"q":"网格蛋白由3条________和3条________组成三脚复合体；衔接蛋白AP起________作用。","a":"重链,轻链,中介接头","kp":"ch04_s0_10"},{"id":"ch04_fill_4","modI":0,"q":"发动蛋白dynamin是________蛋白,提供能量并引起环收缩,将小泡从膜上________。","a":"小G(GTP),掐断","kp":"ch04_s0_16"},{"id":"ch04_fill_5","modI":1,"q":"COPII组装依赖GTP结合蛋白________；COPI组装依赖________；胞吞掐断依赖________。","a":"Sar,ARF,dynamin","kp":"ch04_s1_1"},{"id":"ch04_fill_6","modI":1,"q":"ER驻留蛋白C端的回收信号是________,逃逸后经________小泡回收回ER。","a":"KDEL,COPI","kp":"ch04_s1_5"},{"id":"ch04_fill_7","modI":1,"q":"囊泡停靠中,________(小G蛋白)控制小泡的识别、锚定、停靠；________介导膜融合。","a":"Rab,v-SNARE/t-SNARE","kp":"ch04_s1_8"},{"id":"ch04_fill_8","modI":0,"q":"家族性高胆固醇血症的分子基础是________受体基因缺失或受体无功能。","a":"LDL","kp":"ch04_s0_22"},{"id":"ch04_fill_9","modI":0,"q":"2013年诺贝尔生理学或医学奖授予发现________调节机制的三位科学家。","a":"细胞囊泡运输","kp":"ch04_s0_4"},{"id":"ch04_fill_10","modI":1,"q":"v-SNARE位于________,t-SNARE位于________,二者互补配对介导融合。","a":"运输小泡,靶膜","kp":"ch04_s1_22"},{"id":"ch04_fill_11","modI":0,"q":"LDL颗粒的核心是________,外壳含磷脂、胆固醇和________。","a":"胆固醇酯,载脂蛋白B","kp":"ch04_s0_18"},{"id":"ch04_fill_12","modI":1,"q":"膜泡运输的方向由________决定；Rab高度选择性地分布于不同膜,成为膜的________标志。","a":"包被蛋白,身份(分子)","kp":"ch04_s1_13"}],"short":[{"id":"ch04_short_1","modI":0,"q":"简述膜泡运输的三种类型及其功能。","a":"膜泡运输的三种小泡类型：\n\n①COPII有被小泡(ER→Golgi)：负责从内质网到高尔基体的顺行运输。组装依赖GTP结合蛋白Sar。\n\n②COPI有被小泡(Golgi→ER)：负责回收、转运ER的逃逸蛋白返回ER，也参与高尔基体内部逆向运输。有7个蛋白亚基，依赖ARF。\n\n③网格蛋白有被小泡(Clathrin-coated vesicle)：负责从Golgi TGN→质膜、溶酶体的运输，以及受体介导的胞吞作用。由网格蛋白(triskelion)+衔接蛋白AP+发动蛋白dynamin组成。\n\n【共同点】\n①都由包被蛋白在膜上组装形成；\n②包被蛋白决定运输方向和货物选择；\n③小泡形成后脱去包被，经Rab/SNARE与靶膜识别并融合。\n\n【意义】\n实现内膜系统区室间及细胞与外界之间的物质运输。","kp":"ch04_s0_5"},{"id":"ch04_short_2","modI":0,"q":"简述受体介导的胞吞作用(以LDL为例)。","a":"受体介导的胞吞作用(receptor-mediated endocytosis)：\n\n【以LDL(低密度脂蛋白)为例】\n①LDL结构：核心为约1500分子胆固醇酯，外壳为磷脂、胆固醇和载脂蛋白B。\n②当细胞需要胆固醇时，合成LDL跨膜受体蛋白并插入质膜。\n③质膜上的LDL受体与LDL颗粒结合。\n④膜凹陷，网格蛋白组装，形成网格蛋白包被小泡。\n⑤发动蛋白dynamin在颈部形成环并收缩(GTP供能)，将小泡从膜上掐断。\n⑥小泡脱包被，与溶酶体融合，LDL被降解，胆固醇释放利用，受体回收。\n\n【病理】\n编码LDL受体基因缺失或受体无功能→胆固醇摄入通路阻断→家族性高胆固醇血症。\n\n【意义】\n高效、特异摄取胞外大分子，是细胞摄取胆固醇、铁(转铁蛋白)等的重要方式。","kp":"ch04_s0_14"},{"id":"ch04_short_3","modI":1,"q":"简述小泡运输的停靠和融合机制。","a":"小泡运输的停靠和融合：\n\n【停靠(docking)】\n①Rab蛋白(小G蛋白，60多种)高度选择性地分布在特定膜上，是膜身份的分子标志；\n②运输小泡-Rab-GTP与靶膜上的Rab effector结合，实现识别、锚定、停靠。\n\n【融合(fusion)】\n①小泡脱去包被；\n②小泡表面的v-SNARE与靶膜上的t-SNARE互补配对，形成反式SNARE复合物；\n③SNARE缠绕拉近两膜，NSF/SNAP等胞质蛋白参与，驱动膜融合；\n④小泡内容物释放到靶细胞器内。\n\n【分工】\nRab引导小泡到正确靶膜；SNARE介导膜融合。\n\n【意义】\n保证小泡只与正确的靶膜融合，实现货物精准投递。2013年诺贝尔奖授予相关发现。","kp":"ch04_s1_8"},{"id":"ch04_short_4","modI":0,"q":"比较COPII、COPI和网格蛋白小泡。","a":"三种包被小泡的比较：\n\n| 类型 | 方向 | 包被蛋白 | GTP酶 | 功能 |\n|---|---|---|---|---|\n| COPII | ER→Golgi | COPII(Sec23/24等) | Sar | 顺行运输 |\n| COPI | Golgi→ER | COPI(7亚基) | ARF | 回收逃逸蛋白 |\n| 网格蛋白 | TGN→质膜/溶酶体；胞吞 | 网格蛋白+AP | dynamin/ARF | 分泌、受体介导胞吞 |\n\n【共同点】\n①都在膜上组装包被；②都依赖小GTP酶调控装配；③都脱包被后经Rab/SNARE融合。\n\n【意义】\n不同包被蛋白决定小泡的运输方向与货物选择性。","kp":"ch04_s0_11"},{"id":"ch04_short_5","modI":1,"q":"简述蛋白质分选的类型及信号。","a":"蛋白质分选(protein sorting)：\n\n【按转移时间分类】\n①共翻译转移(co-translational)：蛋白在游离核糖体起始合成后，边翻译边经信号肽引导进入rER(如分泌蛋白、膜蛋白、溶酶体酶)；\n②翻译后转移(post-translational)：蛋白在游离核糖体完全合成后转运至线粒体、叶绿体、过氧化物酶体、细胞核。\n\n【按运输途径分类】\n①膜泡运输(内膜系统)；②跨膜运输(线粒体/叶绿体/过氧化物酶体)；③核孔运输(细胞核)。\n\n【分选信号】\n①信号肽(signal peptide)——N端引导入ER；\n②信号斑(signal patch)——由折叠形成的空间信号；\n③KDEL——ER驻留信号；\n④NLS/NES——核定位/核输出信号；\n⑤M6P——溶酶体分选信号；\n⑥导肽/转运肽——线粒体/叶绿体。\n\n【意义】\n信号序列是蛋白质分选的'邮政编码'，保证蛋白到达正确部位。","kp":"ch04_s1_10"},{"id":"ch04_short_6","modI":0,"q":"为什么说囊泡运输研究重要？简述其发现史。","a":"囊泡运输的重要性与发现史：\n\n【重要性】\n①囊泡运输是真核细胞内膜系统区室间物质交流的主要方式；\n②完成分泌蛋白的运输、胞吞、溶酶体酶分选等基本生命活动；\n③缺陷与多种疾病相关(如家族性高胆固醇血症、神经退行性疾病)；\n④是细胞极性和组织功能的基础。\n\n【发现史】\n①1974年Palade等用放射自显影追踪分泌蛋白路径；\n②1990年代Schekman用酵母遗传学筛选到sec突变体，发现COPII等；\n③Rothman发现SNARE蛋白介导膜融合；\n④Südhof发现神经递质释放的钙感受器；\n⑤2013年Rothman、Schekman、Südhof获诺贝尔生理学或医学奖。\n\n【核心分子】\n包被蛋白(COPII/COPI/网格蛋白)、小G蛋白(Sar/ARF/Rab/dynamin)、SNARE。","kp":"ch04_s0_5"}],"calc":[{"id":"ch04_calc_1","modI":0,"q":"论述膜泡运输的分子机制(从出芽到融合)。","a":"膜泡运输经历出芽、运输、停靠、融合四个阶段,由多组分子协同完成","steps":"【1. 出芽(budding)】\n①包被蛋白在供体膜上组装：COPII(Sar)、COPI(ARF)、网格蛋白(AP)；\n②货物蛋白经信号序列与受体结合，被浓缩入小泡；\n③网格蛋白/COPII形成弯曲的膜，dynamin(GTP)收缩掐断小泡。\n\n【2. 运输(transport)】\n①短距离靠扩散；\n②长距离靠细胞骨架(微管/马达蛋白)运输。\n\n【3. 停靠(docking)】\n①小泡脱去包被；\n②Rab-GTP与靶膜Rab effector结合→识别、锚定、停靠。\n\n【4. 融合(fusion)】\n①v-SNARE(小泡)与t-SNARE(靶膜)互补配对形成反式SNARE复合物；\n②SNARE缠绕拉近两膜；\n③NSF/SNAP等胞质蛋白参与，驱动膜融合；\n④货物释放。\n\n【调控】\n各步骤由小GTP酶(Sar/ARF/Rab/dynamin)精确调控。\n\n【意义】\n保证货物精准投递；2013年诺贝尔奖。","kp":"ch04_s0_5"},{"id":"ch04_calc_2","modI":1,"q":"论述内膜系统蛋白质分选的三条途径及其分子机制。","a":"蛋白质分选有三条途径:膜泡运输、跨膜运输、核孔运输","steps":"【1. 膜泡运输(内膜系统)】\n①共翻译转移：信号肽引导新生肽入ER→经COPII到Golgi→再分选；\n②COPI回收逃逸蛋白(KDEL信号)；\n③网格蛋白小泡运往质膜/溶酶体；\n④溶酶体酶经M6P途径分选。\n\n【2. 跨膜运输(线粒体/叶绿体/过氧化物酶体)】\n①翻译后转移：蛋白在游离核糖体合成；\n②N端导肽/转运肽引导，与膜受体识别；\n③在膜接触点经转运子(TOM/TIM)跨膜进入；\n④导肽被切除，蛋白折叠。\n\n【3. 核孔运输(细胞核)】\n①亲核蛋白含核定位信号(NLS)；\n②NLS与输入蛋白importin结合；\n③经核孔复合体(NPC)入核；\n④Ran-GTP调控货物释放；\n⑤核输出信号(NES)介导出核。\n\n【共同点】\n都依赖蛋白质自身的信号序列；都需受体识别；都消耗能量(GTP/ATP)。\n\n【意义】\n保证每种蛋白到达正确部位，维持细胞区室化。","kp":"ch04_s1_4"},{"id":"ch04_calc_3","modI":0,"q":"论述受体介导的胞吞作用及其在医学上的意义。","a":"受体介导的胞吞是细胞特异、高效摄取胞外大分子的方式,其缺陷导致疾病","steps":"【机制(以LDL为例)】\n①配体(LDL)与质膜受体特异结合；\n②膜凹陷，网格蛋白组装成包被小泡；\n③dynamin收缩掐断小泡；\n④脱包被，与溶酶体融合，配体降解，受体回收循环。\n\n【特点】\n①高度特异(受体-配体)；\n②高效(浓缩富集)；\n③受体可循环利用。\n\n【其他例子】\n①转铁蛋白循环(摄铁)；\n②卵黄脂蛋白摄取；\n③病毒/毒素入侵途径。\n\n【医学意义】\n①家族性高胆固醇血症：LDL受体基因缺失/无功能→胆固醇摄入阻断→动脉粥样硬化；\n②药物靶向：利用受体介导胞吞递送药物；\n③病原体利用此途径感染(如病毒)；\n④为基因治疗、纳米药物设计提供思路。","kp":"ch04_s0_14"}],"term":[{"id":"ch04_term_1","modI":0,"term":"膜泡运输(Vesicular Transport)","def":"①通过膜性小泡在细胞器间运输物质的方式（定义）。②三种小泡：COPII(ER→Golgi)、COPI(Golgi→ER回收)、网格蛋白小泡(TGN→质膜/溶酶体、胞吞)（类型）。③过程：出芽→运输→停靠→融合（过程）。④意义：内膜系统区室间物质交流的主要方式（意义）。","kps":"踩分点:①定义(1分)②三种小泡(1分)③过程(1分)④意义(1分)","kp":"ch04_s0_6"},{"id":"ch04_term_2","modI":1,"term":"COPII有被小泡","def":"①负责从内质网到高尔基体顺行运输的小泡（定义）。②组装：GTP结合蛋白Sar-GTP结合ER膜，诱导COPII蛋白亚单位(Sec23/Sec24等)组装（机制）。③功能：ER→Golgi运输（功能）。","kps":"踩分点:①定义(1分)②Sar依赖(1分)③功能(1分)","kp":"ch04_s1_0"},{"id":"ch04_term_3","modI":1,"term":"COPI有被小泡","def":"①负责回收ER逃逸蛋白返回ER的小泡（定义）。②组成：7个蛋白亚基+ARF(GTP结合蛋白)（组成）。③功能：Golgi→ER逆向运输、回收驻留蛋白（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(1分)","kp":"ch04_s1_0"},{"id":"ch04_term_4","modI":0,"term":"网格蛋白有被小泡(Clathrin-coated Vesicle)","def":"①由网格蛋白包被的小泡（定义）。②组成：网格蛋白(3重链+3轻链三脚复合体)+衔接蛋白AP+发动蛋白dynamin（组成）。③功能：Golgi TGN→质膜/溶酶体运输；受体介导的胞吞作用（功能）。","kps":"踩分点:①定义(1分)②组成(1分)③功能(2分)","kp":"ch04_s0_9"},{"id":"ch04_term_5","modI":0,"term":"发动蛋白(Dynamin)","def":"①参与胞吞的小GTP蛋白（定义）。②功能：提供能量、引起环收缩，将小泡从膜上掐断（功能）。③位置：网格蛋白小泡颈部（位置）。","kps":"踩分点:①定义(1分)②功能(2分)③位置(1分)","kp":"ch04_s0_16"},{"id":"ch04_term_6","modI":0,"term":"受体介导的胞吞作用","def":"①细胞通过质膜受体特异结合胞外大分子并内吞的过程（定义）。②过程：配体-受体结合→网格蛋白包被→dynamin掐断→脱包被→与溶酶体融合（过程）。③举例：LDL(胆固醇)、转铁蛋白(铁)（举例）。④病理：LDL受体缺陷→家族性高胆固醇血症（病理）。","kps":"踩分点:①定义(1分)②过程(1分)③举例(1分)④病理(1分)","kp":"ch04_s0_14"},{"id":"ch04_term_7","modI":1,"term":"Rab蛋白","def":"①GTP酶超家族的开关蛋白，60多种（定义）。②特点：高度选择性地分布在特定膜上，是膜身份的分子标志（特点）。③功能：控制转运小泡在靶膜的识别、锚定、停靠（功能）。","kps":"踩分点:①定义(1分)②特点(1分)③功能(2分)","kp":"ch04_s1_12"},{"id":"ch04_term_8","modI":1,"term":"SNARE蛋白","def":"①介导膜泡与靶膜融合的蛋白家族（定义）。②分类：v-SNARE(小泡上)、t-SNARE(靶膜上)（分类）。③机制：v-SNARE与t-SNARE互补配对形成反式SNARE复合物，拉近两膜驱动融合（机制）。④意义：保证小泡只与正确靶膜融合；2013年诺贝尔奖（意义）。","kps":"踩分点:①定义(1分)②分类(1分)③机制(1分)④意义(1分)","kp":"ch04_s1_11"},{"id":"ch04_term_9","modI":1,"term":"KDEL回收信号","def":"①ER驻留蛋白C端的一段回收信号序列(KDEL)（定义）。②功能：使Bip、PDI等驻留蛋白被保留在ER中（功能）。③机制：逃逸到高尔基体的驻留蛋白被KDEL受体识别，经COPI小泡回收回ER（机制）。","kps":"踩分点:①定义(1分)②功能(1分)③机制(2分)","kp":"ch04_s1_5"},{"id":"ch04_term_10","modI":1,"term":"共翻译转移(Cotranslational Translocation)","def":"①蛋白质在游离核糖体起始合成后，边翻译边经信号肽引导进入ER的过程（定义）。②机制：信号肽-SRP-核糖体复合物结合ER膜SRP受体→共翻译转移入ER腔（机制）。③对象：分泌蛋白、膜蛋白、溶酶体酶（对象）。","kps":"踩分点:①定义(1分)②机制(1分)③对象(1分)","kp":"ch04_s1_16"},{"id":"ch04_term_11","modI":1,"term":"翻译后转移(Post-translational Translocation)","def":"①蛋白质在细胞质游离核糖体完全合成后，再转运至特定细胞器的过程（定义）。②对象：线粒体、叶绿体、过氧化物酶体、细胞核蛋白（对象）。③特点：需N端导肽/转运肽引导，需解折叠（特点）。","kps":"踩分点:①定义(1分)②对象(2分)③特点(1分)","kp":"ch04_s1_16"},{"id":"ch04_term_12","modI":0,"term":"家族性高胆固醇血症","def":"①由LDL受体基因缺陷导致的遗传病（定义）。②机制：LDL受体缺失或无功能→胆固醇摄入通路阻断→细胞不能摄取胆固醇→血液胆固醇升高→动脉粥样硬化（机制）。③意义：是受体介导胞吞重要性的经典例证（意义）。","kps":"踩分点:①定义(1分)②机制(2分)③意义(1分)","kp":"ch04_s0_22"},{"id":"ch04_term_13","modI":0,"term":"衔接蛋白(Adaptor Protein, AP)","def":"①网格蛋白小泡中连接网格蛋白与货物受体的蛋白（定义）。②功能：中介接头作用，选择货物并将其与网格蛋白连接（功能）。③意义：决定网格蛋白小泡的货物选择性（意义）。","kps":"踩分点:①定义(1分)②功能(2分)③意义(1分)","kp":"ch04_s0_11"},{"id":"ch04_term_14","modI":1,"term":"膜融合(Membrane Fusion)","def":"①运输小泡与靶膜脂双层合并、内容物释放的过程（定义）。②机制：v-SNARE与t-SNARE配对形成反式复合物，拉近两膜；NSF/SNAP等参与（机制）。③前提：小泡脱去包被（前提）。","kps":"踩分点:①定义(1分)②机制(2分)③前提(1分)","kp":"ch04_s1_16"},{"id":"ch04_term_15","modI":1,"term":"组成型分泌与调节型分泌","def":"①组成型分泌：小泡持续与质膜融合、不断分泌（定义）。②调节型分泌：小泡储存于胞内，需信号(激素/神经递质)触发才与质膜融合释放（定义）。③意义：调节型分泌实现信号的精确调控(如神经递质释放)（意义）。","kps":"踩分点:①组成型(1分)②调节型(2分)③意义(1分)","kp":"ch04_s1_6"}],"preview":{"main":"本章讲解细胞内蛋白质运输中的膜泡运输机制：蛋白质如何通过共翻译或翻译后途径进入细胞器，以及细胞如何利用不同包被小泡（网格蛋白、COPI、COPII）在内膜系统中有组织地运输货物，并通过Rab与SNARE等分子机器实现小泡的精准停靠与融合。理解这一章是掌握细胞内膜系统区室化、物质分选与定向运输的核心，也是解释LDL受体途径、家族性高胆固醇血症等生理病理现象的基础。","questions":["蛋白质输入细胞器的三种途径分别是什么？共翻译转移与翻译后转移在机制和适用对象上有何区别？","网格蛋白有被小泡由哪些成分组成？网格蛋白和发动蛋白dynamin在小泡形成与释放中各自起什么作用？","受体介导的内吞包括哪些主要步骤？LDL受体途径如何体现货物蛋白的靶向运输，家族性高胆固醇血症与这一途径有何关系？","COPII与COPI有被小泡分别负责什么方向的运输？Sar蛋白如何参与COPII组装，驻留蛋白的保留与回收信号机制是什么？","Rab蛋白和SNARE蛋白在小泡停靠与融合中如何分工？v-SNARE与t-SNARE如何保证融合的选择性和方向性？","小泡运输的停靠和融合可分为哪两步？膜融合为什么需要胞质蛋白参与，脱包被后融合的意义是什么？"]},"appcards":[{"front":"简述膜泡运输的三种类型及其功能。","back":"膜泡运输的三种小泡类型：\n\n①COPII有被小泡(ER→Golgi)：负责从内质网到高尔基体的顺行运输。组装依赖GTP结合蛋白Sar。\n\n②COPI有被小泡(Golgi→ER)：负责回收、转运ER的逃逸蛋白返回ER，也参与高尔基体内部逆向运输。有7个蛋白亚基，依赖ARF。\n\n③网格蛋白有被小泡(Clathrin-coated vesicle)：负责从Golgi TGN→质膜、溶酶体的运输，以及受体介导的胞吞作用。由网格蛋白(triskelion)+衔接蛋白AP+发动蛋白dynamin组成。\n\n【共同点】\n①都由包被蛋白在膜上组装形成；\n②包被蛋白决定运输方向和货物选择；\n③小泡形成后脱去包被，经Rab/SNARE与靶膜识别并融合。\n\n【意义】\n实现内膜系统区室间及细胞与外界之间的物质运输。","points":"","mod":0,"modName":"模块一：运输途径与网格蛋白小泡","level":"掌握","src":"题库"},{"front":"简述受体介导的胞吞作用(以LDL为例)。","back":"受体介导的胞吞作用(receptor-mediated endocytosis)：\n\n【以LDL(低密度脂蛋白)为例】\n①LDL结构：核心为约1500分子胆固醇酯，外壳为磷脂、胆固醇和载脂蛋白B。\n②当细胞需要胆固醇时，合成LDL跨膜受体蛋白并插入质膜。\n③质膜上的LDL受体与LDL颗粒结合。\n④膜凹陷，网格蛋白组装，形成网格蛋白包被小泡。\n⑤发动蛋白dynamin在颈部形成环并收缩(GTP供能)，将小泡从膜上掐断。\n⑥小泡脱包被，与溶酶体融合，LDL被降解，胆固醇释放利用，受体回收。\n\n【病理】\n编码LDL受体基因缺失或受体无功能→胆固醇摄入通路阻断→家族性高胆固醇血症。\n\n【意义】\n高效、特异摄取胞外大分子，是细胞摄取胆固醇、铁(转铁蛋白)等的重要方式。","points":"","mod":0,"modName":"模块一：运输途径与网格蛋白小泡","level":"掌握","src":"题库"},{"front":"简述小泡运输的停靠和融合机制。","back":"小泡运输的停靠和融合：\n\n【停靠(docking)】\n①Rab蛋白(小G蛋白，60多种)高度选择性地分布在特定膜上，是膜身份的分子标志；\n②运输小泡-Rab-GTP与靶膜上的Rab effector结合，实现识别、锚定、停靠。\n\n【融合(fusion)】\n①小泡脱去包被；\n②小泡表面的v-SNARE与靶膜上的t-SNARE互补配对，形成反式SNARE复合物；\n③SNARE缠绕拉近两膜，NSF/SNAP等胞质蛋白参与，驱动膜融合；\n④小泡内容物释放到靶细胞器内。\n\n【分工】\nRab引导小泡到正确靶膜；SNARE介导膜融合。\n\n【意义】\n保证小泡只与正确的靶膜融合，实现货物精准投递。2013年诺贝尔奖授予相关发现。","points":"","mod":1,"modName":"模块二：COP小泡与停靠融合","level":"掌握","src":"题库"},{"front":"比较COPII、COPI和网格蛋白小泡。","back":"三种包被小泡的比较：\n\n| 类型 | 方向 | 包被蛋白 | GTP酶 | 功能 |\n|---|---|---|---|---|\n| COPII | ER→Golgi | COPII(Sec23/24等) | Sar | 顺行运输 |\n| COPI | Golgi→ER | COPI(7亚基) | ARF | 回收逃逸蛋白 |\n| 网格蛋白 | TGN→质膜/溶酶体；胞吞 | 网格蛋白+AP | dynamin/ARF | 分泌、受体介导胞吞 |\n\n【共同点】\n①都在膜上组装包被；②都依赖小GTP酶调控装配；③都脱包被后经Rab/SNARE融合。\n\n【意义】\n不同包被蛋白决定小泡的运输方向与货物选择性。","points":"","mod":0,"modName":"模块一：运输途径与网格蛋白小泡","level":"掌握","src":"题库"},{"front":"简述蛋白质分选的类型及信号。","back":"蛋白质分选(protein sorting)：\n\n【按转移时间分类】\n①共翻译转移(co-translational)：蛋白在游离核糖体起始合成后，边翻译边经信号肽引导进入rER(如分泌蛋白、膜蛋白、溶酶体酶)；\n②翻译后转移(post-translational)：蛋白在游离核糖体完全合成后转运至线粒体、叶绿体、过氧化物酶体、细胞核。\n\n【按运输途径分类】\n①膜泡运输(内膜系统)；②跨膜运输(线粒体/叶绿体/过氧化物酶体)；③核孔运输(细胞核)。\n\n【分选信号】\n①信号肽(signal peptide)——N端引导入ER；\n②信号斑(signal patch)——由折叠形成的空间信号；\n③KDEL——ER驻留信号；\n④NLS/NES——核定位/核输出信号；\n⑤M6P——溶酶体分选信号；\n⑥导肽/转运肽——线粒体/叶绿体。\n\n【意义】\n信号序列是蛋白质分选的'邮政编码'，保证蛋白到达正确部位。","points":"","mod":1,"modName":"模块二：COP小泡与停靠融合","level":"掌握","src":"题库"},{"front":"为什么说囊泡运输研究重要？简述其发现史。","back":"囊泡运输的重要性与发现史：\n\n【重要性】\n①囊泡运输是真核细胞内膜系统区室间物质交流的主要方式；\n②完成分泌蛋白的运输、胞吞、溶酶体酶分选等基本生命活动；\n③缺陷与多种疾病相关(如家族性高胆固醇血症、神经退行性疾病)；\n④是细胞极性和组织功能的基础。\n\n【发现史】\n①1974年Palade等用放射自显影追踪分泌蛋白路径；\n②1990年代Schekman用酵母遗传学筛选到sec突变体，发现COPII等；\n③Rothman发现SNARE蛋白介导膜融合；\n④Südhof发现神经递质释放的钙感受器；\n⑤2013年Rothman、Schekman、Südhof获诺贝尔生理学或医学奖。\n\n【核心分子】\n包被蛋白(COPII/COPI/网格蛋白)、小G蛋白(Sar/ARF/Rab/dynamin)、SNARE。","points":"","mod":0,"modName":"模块一：运输途径与网格蛋白小泡","level":"掌握","src":"题库"},{"front":"论述膜泡运输的分子机制(从出芽到融合)。","back":"【1. 出芽(budding)】\n①包被蛋白在供体膜上组装：COPII(Sar)、COPI(ARF)、网格蛋白(AP)；\n②货物蛋白经信号序列与受体结合，被浓缩入小泡；\n③网格蛋白/COPII形成弯曲的膜，dynamin(GTP)收缩掐断小泡。\n\n【2. 运输(transport)】\n①短距离靠扩散；\n②长距离靠细胞骨架(微管/马达蛋白)运输。\n\n【3. 停靠(docking)】\n①小泡脱去包被；\n②Rab-GTP与靶膜Rab effector结合→识别、锚定、停靠。\n\n【4. 融合(fusion)】\n①v-SNARE(小泡)与t-SNARE(靶膜)互补配对形成反式SNARE复合物；\n②SNARE缠绕拉近两膜；\n③NSF/SNAP等胞质蛋白参与，驱动膜融合；\n④货物释放。\n\n【调控】\n各步骤由小GTP酶(Sar/ARF/Rab/dynamin)精确调控。\n\n【意义】\n保证货物精准投递；2013年诺贝尔奖。","points":"","mod":0,"modName":"模块一：运输途径与网格蛋白小泡","level":"掌握","src":"题库"},{"front":"论述内膜系统蛋白质分选的三条途径及其分子机制。","back":"【1. 膜泡运输(内膜系统)】\n①共翻译转移：信号肽引导新生肽入ER→经COPII到Golgi→再分选；\n②COPI回收逃逸蛋白(KDEL信号)；\n③网格蛋白小泡运往质膜/溶酶体；\n④溶酶体酶经M6P途径分选。\n\n【2. 跨膜运输(线粒体/叶绿体/过氧化物酶体)】\n①翻译后转移：蛋白在游离核糖体合成；\n②N端导肽/转运肽引导，与膜受体识别；\n③在膜接触点经转运子(TOM/TIM)跨膜进入；\n④导肽被切除，蛋白折叠。\n\n【3. 核孔运输(细胞核)】\n①亲核蛋白含核定位信号(NLS)；\n②NLS与输入蛋白importin结合；\n③经核孔复合体(NPC)入核；\n④Ran-GTP调控货物释放；\n⑤核输出信号(NES)介导出核。\n\n【共同点】\n都依赖蛋白质自身的信号序列；都需受体识别；都消耗能量(GTP/ATP)。\n\n【意义】\n保证每种蛋白到达正确部位，维持细胞区室化。","points":"","mod":1,"modName":"模块二：COP小泡与停靠融合","level":"掌握","src":"题库"},{"front":"论述受体介导的胞吞作用及其在医学上的意义。","back":"【机制(以LDL为例)】\n①配体(LDL)与质膜受体特异结合；\n②膜凹陷，网格蛋白组装成包被小泡；\n③dynamin收缩掐断小泡；\n④脱包被，与溶酶体融合，配体降解，受体回收循环。\n\n【特点】\n①高度特异(受体-配体)；\n②高效(浓缩富集)；\n③受体可循环利用。\n\n【其他例子】\n①转铁蛋白循环(摄铁)；\n②卵黄脂蛋白摄取；\n③病毒/毒素入侵途径。\n\n【医学意义】\n①家族性高胆固醇血症：LDL受体基因缺失/无功能→胆固醇摄入阻断→动脉粥样硬化；\n②药物靶向：利用受体介导胞吞递送药物；\n③病原体利用此途径感染(如病毒)；\n④为基因治疗、纳米药物设计提供思路。","points":"","mod":0,"modName":"模块一：运输途径与网格蛋白小泡","level":"掌握","src":"题库"},{"front":"囊泡运输、跨膜运输和核孔运输三种蛋白质输入细胞器途径有何异同？","back":"相同：均将蛋白质定向送入细胞器；不同：囊泡运输靠膜泡完成内膜系统间及胞内外交流；跨膜运输经线粒体、叶绿体、过氧化物酶体膜；核孔运输经核孔入核。","points":"相同点；囊泡运输；跨膜运输；核孔运输","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说核孔运输、跨膜运输和膜泡运输对应的细胞器不同？","back":"核孔运输对应细胞核；跨膜运输对应线粒体、叶绿体、过氧化物酶体及信号肽引导入ER；膜泡运输对应内膜系统各区室。","points":"核孔-核；跨膜-线粒体/叶绿体/过氧化物酶体；膜泡-内膜系统","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"共翻译转移与翻译后转移有何异同？","back":"相同：都需信号引导蛋白质到特定部位；不同：共翻译转移在肽链合成中入rER，经小泡到Golgi等；翻译后转移在游离核糖体完成后入线粒体、叶绿体、过氧化物酶体等。","points":"相同点；共翻译入rER；翻译后入线粒体等","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么分泌蛋白通常采用共翻译转移途径？","back":"分泌蛋白N端信号肽在游离核糖体合成后即被SRP识别，引导核糖体到rER；肽链边合成边入ER腔，再经Golgi、分泌小泡到胞外。","points":"信号肽；SRP；rER；边合成边转运","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"2013年诺贝尔生理学或医学奖对囊泡运输研究有什么意义？","back":"授予Rothman、Schekman、Südhof；阐明囊泡运输调节机制和货物准确投递的分子原理；确立Rab、SNARE等核心机制。","points":"获奖者；囊泡运输调节；分子原理；Rab/SNARE","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"囊泡运输的核心问题是什么？","back":"阐明货物如何被包入小泡并被运送到正确位置的分子原理；包括出芽、包被、运输、停靠、融合和货物定向。","points":"货物；正确位置；分子原理；出芽到融合","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"COPII、COPI和网格蛋白有被小泡在运输方向上有何异同？","back":"相同：均为包被小泡；不同：COPII介导ER→Golgi顺行；COPI介导Golgi→ER回收及Golgi内逆向；网格蛋白介导TGN→质膜/溶酶体及受体介导胞吞。","points":"COPII顺行；COPI回收；网格蛋白TGN/胞吞","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么内膜系统的小泡转运被称为有组织运输？","back":"因为存在向外分泌途径和向内胞吞途径；小泡按特定方向、特定靶膜运输；ER→Golgi→质膜/溶酶体与胞吞入胞高度有序。","points":"向外分泌；向内胞吞；方向性；有序","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"网格蛋白有被小泡的结构组成有哪些？各有什么作用？","back":"网格蛋白形成外壳；衔接蛋白AP连接网格蛋白与货物受体；货物受体结合货物；发动蛋白负责小泡从膜上掐断。","points":"网格蛋白；AP；货物受体；dynamin","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"网格蛋白三脚蛋白复合体如何组装成包被小泡？","back":"网格蛋白由3条重链和3条轻链组成三脚蛋白复合体；多个triskelion组装成多边形网格；包被膜凹陷形成有被小泡。","points":"重链；轻链；triskelion；多边形网格","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"发动蛋白dynamin在胞吞中有什么作用？","back":"dynamin是小GTP蛋白；在网格蛋白小泡颈部组装；水解GTP提供能量，引起环收缩；将小泡从质膜上掐断。","points":"小GTP蛋白；颈部；GTP供能；掐断","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明网格蛋白有被小泡的功能。","back":"Golgi TGN内蛋白浓缩入小泡运向质膜或溶酶体；细胞外LDL与质膜受体结合后形成网格蛋白小泡，经受体介导内吞入胞。","points":"TGN→质膜/溶酶体；LDL；受体介导内吞","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"受体介导的内吞作用基本步骤是什么？","back":"配体与质膜受体结合；膜凹陷；网格蛋白包被；形成小泡；dynamin掐断；小泡脱包被并与溶酶体融合。","points":"配体-受体；膜凹陷；网格蛋白；掐断；溶酶体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"LDL如何通过受体介导途径参与胆固醇摄取？","back":"细胞需胆固醇时合成LDL受体并插入质膜；受体结合LDL后形成网格蛋白小泡；小泡与溶酶体融合；胆固醇释放供利用。","points":"LDL受体；网格蛋白小泡；溶酶体；胆固醇释放","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么LDL受体基因缺失会导致家族性高胆固醇血症？","back":"LDL受体缺失或无功能；胆固醇摄入通路阻断；细胞不能摄取LDL；血液胆固醇升高；导致家族性高胆固醇血症。","points":"受体缺失/无功能；摄入阻断；血胆固醇升高","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"Sar蛋白如何启动COPII有被小泡组装？","back":"Sar-GDP转为Sar-GTP后被激活；Sar-GTP结合ER膜；GTP激发构型变化；诱导Sec23/Sec24、Sec13/Sec31等COPII亚单位组装成包被。","points":"Sar-GTP；ER膜；构型变化；COPII亚单位","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"COPI有被小泡有什么作用？","back":"负责回收ER逃逸蛋白返回ER；参与高尔基体内部逆向运输；由7个蛋白亚基和ARF组成；装配依赖ARF。","points":"回收逃逸蛋白；逆向运输；ARF；7亚基","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"ER驻留蛋白如果逃逸到高尔基体会怎样？","back":"其C端KDEL等回收信号被KDEL受体识别；经COPI小泡回收回ER；从而维持ER驻留蛋白定位。","points":"KDEL；受体识别；COPI；回收回ER","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"Rab蛋白和SNARE蛋白在囊泡运输中的分工有何不同？","back":"Rab是小GTP酶开关蛋白；引导小泡到正确靶膜并控制停靠；SNARE中v-SNARE与t-SNARE配对；介导膜融合。","points":"Rab引导/停靠；SNARE配对；介导融合","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么Rab蛋白可作为膜身份的分子标志？","back":"Rab属于GTP酶超家族开关蛋白；有60多种；每种高度选择性地定位到特定膜系统；因此不同膜具有不同Rab标志。","points":"GTP酶；60多种；选择性定位；膜标志","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"v-SNARE与t-SNARE如何保证小泡只与正确靶膜融合？","back":"小泡表面携带特异v-SNARE；靶膜有互补t-SNARE；二者特异性配对；如ER来源小泡与Golgi靶膜SNARE配对，保证定向融合。","points":"v-SNARE；t-SNARE；互补配对；定向融合","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"小泡脱包被对其与靶膜融合有什么意义？","back":"包被脱去后暴露v-SNARE等融合装置；小泡才能与靶膜识别、停靠和融合；脱包被是融合前提。","points":"脱包被；暴露v-SNARE；识别停靠；融合前提","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"小泡停靠和融合为什么需要两步识别？","back":"第一步Rab-GTP与靶膜Rab效应器识别、锚定；第二步v-SNARE与t-SNARE配对；两步提高特异性，保证正确投递和融合。","points":"Rab-效应器；v/t-SNARE；两步；特异性","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞中dynamin功能被抑制，受体介导内吞会怎样？","back":"网格蛋白小泡可在膜上形成；但小泡颈部不能收缩掐断；内吞小泡无法释放入胞；LDL等摄取受阻。","points":"小泡形成；不能掐断；内吞受阻；LDL摄取","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若ER驻留蛋白KDEL回收信号缺失，会产生什么后果？","back":"逃逸到Golgi的ER驻留蛋白不能被KDEL受体识别；不能经COPI回收；可能继续分泌到胞外；ER驻留蛋白定位异常。","points":"KDEL缺失；受体不识别；COPI回收失败；定位异常","mod":null,"modName":"应用综合","level":"掌握","src":"生成"}]};